import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Battery, 
  Wifi, 
  MapPin, 
  Wind, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  Camera, 
  ArrowUp,
  Droplets,
  Zap,
  Radio,
  Crosshair,
  AlertTriangle,
  Flame,
  ZapOff,
  CloudLightning,
  RefreshCw
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  YAxis, 
  XAxis, 
  Tooltip, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage } from './types';
import { getAIDecision } from './services/geminiService';

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120,
    speed: 45,
    battery: 88,
    gpsSignal: 95,
    windSpeed: 12,
    pitch: 2,
    roll: -1,
    yaw: 185,
    heading: 185,
    connectionStrength: 98,
    isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [userInput, setUserInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const lastAutoAnalysis = useRef<number>(0);

  // --- AI Logic Integration ---
  const handleAIRequest = useCallback(async (input?: string, autoTrigger = false) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const text = input || userInput || "Review current telemetry and mission status.";

    if (!autoTrigger) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'OPERATOR',
        content: text
      }]);
    } else {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `AUTOMATIC SAFETY SCAN TRIGGERED: ${text}`
      }]);
    }

    const aiResponse = await getAIDecision(telemetry, currentMode, currentMission, text);

    // Parse the response for commands
    if (aiResponse.includes('COMMAND:')) {
      const command = aiResponse.split('COMMAND:')[1].trim().split('\n')[0];
      if (command.includes('RTL')) setCurrentMode(FlightMode.RETURN_TO_HOME);
      if (command.includes('LAND')) setCurrentMode(FlightMode.EMERGENCY_LANDING);
      if (command.includes('WATER')) setTelemetry(t => ({...t, isWaterproofMode: true}));
    }

    setMessages(prev => [...prev, {
      id: (Date.now() + 1).toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: aiResponse
    }]);

    setIsProcessing(false);
    setUserInput("");
  }, [telemetry, currentMode, currentMission, userInput, isProcessing]);

  // --- Effects ---
  useEffect(() => {
    setMessages([{
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "UAV CORE INITIALIZED. AEGIS-CORE v4.0 ONLINE. ALL SENSORS CALIBRATED."
    }]);

    const interval = setInterval(() => {
      setTelemetry(prev => ({
        ...prev,
        altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * (prev.altitude > 10 ? 1 : 0.1)),
        speed: Math.max(0, prev.speed + (Math.random() - 0.5) * 2),
        battery: Math.max(0, prev.battery - (isEmergency ? 0.05 : 0.01)),
        pitch: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        roll: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        heading: (prev.heading + 0.1) % 360,
        gpsSignal: isEmergency ? Math.max(5, prev.gpsSignal - Math.random()) : prev.gpsSignal,
        windSpeed: isEmergency ? Math.min(60, prev.windSpeed + Math.random()) : prev.windSpeed,
      }));
    }, 1000);

    return () => clearInterval(interval);
  }, [isEmergency]);

  // Auto-analysis of safety thresholds
  useEffect(() => {
    const now = Date.now();
    if (now - lastAutoAnalysis.current < 15000) return; // Only auto-analyze every 15s max

    const isCritical = telemetry.battery < 20 || telemetry.gpsSignal < 30 || telemetry.windSpeed > 35;

    if (isCritical && !isProcessing) {
      lastAutoAnalysis.current = now;
      handleAIRequest("CRITICAL SYSTEM ALERT DETECTED. SENSORS INDICATE UNSAFE OPERATING PARAMETERS.", true);
    }
  }, [telemetry, isProcessing, handleAIRequest]);

  useEffect(() => {
    setTelemetryHistory(prev => {
      const next = [...prev, { time: new Date().toLocaleTimeString(), alt: telemetry.altitude, battery: telemetry.battery }];
      return next.slice(-20);
    });
  }, [telemetry.altitude, telemetry.battery]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const triggerEmergency = () => {
    setIsEmergency(true);
    setTelemetry(t => ({
      ...t,
      gpsSignal: 15,
      windSpeed: 45,
      battery: 19,
      connectionStrength: 25
    }));
    handleAIRequest("SIMULATED CATASTROPHIC FAILURE: GPS LOSS & HIGH WIND DETECTED.", true);
  };

  const resetSystem = () => {
    setIsEmergency(false);
    setTelemetry({
      altitude: 120,
      speed: 45,
      battery: 88,
      gpsSignal: 95,
      windSpeed: 12,
      pitch: 2,
      roll: -1,
      yaw: 185,
      heading: 185,
      connectionStrength: 98,
      isWaterproofMode: false
    });
    setCurrentMode(FlightMode.ASSISTED);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "SYSTEM RESET. ALL PARAMETERS RETURNED TO NOMINAL."
    }]);
  };

  const getStatusColor = (val: number, thresholdLow: number, thresholdWarn: number) => {
    if (val <= thresholdLow) return 'text-red-500';
    if (val <= thresholdWarn) return 'text-yellow-500';
    return 'text-cyan-400';
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {isEmergency && (
        <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden opacity-20 bg-red-900/10">
           <div className="absolute top-0 left-0 w-full h-full animate-[wiggle_0.5s_infinite] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
        </div>
      )}

      {/* --- TOP HUD BAR --- */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter">System Hardware</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`${isEmergency ? 'text-red-500 animate-bounce' : 'text-cyan-400 animate-pulse'}`} />
              <span className={`font-bold tracking-widest ${isEmergency ? 'text-red-400' : 'text-cyan-400'}`}>AEGIS-CORE v4.0</span>
            </div>
          </div>

          <div className="h-8 w-px bg-zinc-700" />

          <div className="flex items-center gap-4">
            <div className="flex flex-col items-center">
               <Battery size={18} className={getStatusColor(telemetry.battery, 20, 35)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.battery, 20, 35)}`}>
                 {telemetry.battery.toFixed(1)}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <Radio size={18} className={getStatusColor(telemetry.connectionStrength, 15, 40)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.connectionStrength, 15, 40)}`}>
                 {telemetry.connectionStrength}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <MapPin size={18} className={getStatusColor(telemetry.gpsSignal, 30, 60)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.gpsSignal, 30, 60)}`}>
                 {telemetry.gpsSignal}%
               </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6">
           <div className="text-right">
            <span className="text-[10px] text-zinc-500 uppercase">Mission Domain</span>
            <div className="text-cyan-400 font-bold text-sm">{currentMission}</div>
          </div>
          <div className={`px-4 py-1 border rounded text-xs font-bold animate-pulse ${
            currentMode === FlightMode.RETURN_TO_HOME || currentMode === FlightMode.EMERGENCY_LANDING 
            ? 'bg-red-900/40 border-red-500 text-red-400' 
            : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'
          }`}>
            {currentMode}
          </div>
          <button 
            onClick={resetSystem}
            className="p-2 hover:bg-zinc-800 rounded text-zinc-400 transition-colors"
            title="System Reset"
          >
            <RefreshCw size={18} />
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">

        {/* --- LEFT: SENSOR DATA & GAUGES --- */}
        <div className="w-1/4 flex flex-col gap-4 overflow-y-auto">

          {/* Altitude Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Altitude (AGL)</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.altitude / 500) * 100)}%` }}></div>
            </div>
          </div>

          {/* Speed Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Ground Velocity</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.speed / 120) * 100)}%` }}></div>
            </div>
          </div>

          {/* Environmental */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-yellow-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-4 block">Navigation & Environment</span>
            <div className="grid grid-cols-2 gap-2 text-center">
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">PITCH</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.pitch) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.pitch.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">ROLL</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.roll) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.roll.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">HEADING</span>
                  <span className="text-cyan-400 text-sm font-bold">{telemetry.heading.toFixed(0)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">WIND VEC</span>
                  <span className={`text-sm font-bold ${telemetry.windSpeed > 35 ? 'text-red-500 animate-pulse' : 'text-yellow-500'}`}>{telemetry.windSpeed.toFixed(0)} km/h</span>
               </div>
            </div>
          </div>

          {/* Chart Area */}
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-2 min-h-[180px] overflow-hidden">
             <div className="h-1/2 w-full flex flex-col">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Alt Profile</span>
                <ResponsiveContainer width="100%" height="80%">
                  <AreaChart data={telemetryHistory}>
                    <Area type="monotone" dataKey="alt" stroke="#00ffcc" fillOpacity={0.1} fill="#00ffcc" isAnimationActive={false} />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
             <div className="h-1/2 w-full flex flex-col mt-2">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Battery Trend</span>
                <ResponsiveContainer width="100%" height="80%">
                  <LineChart data={telemetryHistory}>
                    <Line type="stepAfter" dataKey="battery" stroke="#f59e0b" dot={false} strokeWidth={2} isAnimationActive={false} />
                  </LineChart>
                </ResponsiveContainer>
             </div>
          </div>

        </div>

        {/* --- CENTER: CAMERA / FLIGHT VIEW --- */}
        <div className="flex-1 flex flex-col gap-4 relative">
          <div className="flex-1 bg-zinc-950 rounded-lg relative overflow-hidden group border border-zinc-800">
            <img 
              src={`https://picsum.photos/seed/${currentMission + (isEmergency ? 'fail' : 'norm')}/1280/720`} 
              className={`w-full h-full object-cover mix-blend-screen transition-opacity duration-1000 ${isEmergency ? 'opacity-40 grayscale sepia' : 'opacity-70'}`} 
              alt="UAV View"
            />
            {/* HUD Overlays */}
            <div className="absolute inset-0 pointer-events-none p-6">
              {/* Corner Crosshairs */}
              <div className="absolute top-4 left-4 w-12 h-12 border-t-2 border-l-2 border-cyan-500/30" />
              <div className="absolute top-4 right-4 w-12 h-12 border-t-2 border-r-2 border-cyan-500/30" />
              <div className="absolute bottom-4 left-4 w-12 h-12 border-b-2 border-l-2 border-cyan-500/30" />
              <div className="absolute bottom-4 right-4 w-12 h-12 border-b-2 border-r-2 border-cyan-500/30" />

              {/* Central Reticle */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center">
                 <div className={`w-64 h-[1px] ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className={`absolute w-[1px] h-64 ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className="w-12 h-12 border-2 border-cyan-500/40 rounded-full animate-ping opacity-30" />
                 <div className="w-6 h-6 border border-cyan-500/50" />
              </div>

              <div className="absolute top-8 left-1/2 -translate-x-1/2 text-cyan-400 font-mono text-lg tracking-[0.4em] uppercase opacity-80 flex items-center gap-2">
                {isEmergency ? <AlertTriangle className="text-red-500 animate-pulse" /> : <Activity className="text-cyan-500" />}
                {currentMission} {isEmergency ? 'INTERRUPTED' : 'FEED'}
              </div>

              <div className="absolute bottom-12 left-12 font-mono text-[10px] text-cyan-500/50">
                LAT: 34.0522° N<br/>
                LON: 118.2437° W<br/>
                UTC: {new Date().toISOString()}
              </div>
            </div>

            {/* Failsafe Visuals */}
            {(telemetry.battery < 20 || isEmergency) && (
              <div className="absolute inset-0 bg-red-900/10 border-4 border-red-600/50 animate-[pulse_1s_infinite] flex items-center justify-center flex-col gap-4 backdrop-blur-[1px]">
                 <AlertTriangle size={80} className="text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
                 <div className="bg-black/80 px-6 py-2 border border-red-500 text-red-500 text-xl font-black tracking-widest uppercase">
                    Critical System Alarm
                 </div>
                 <span className="text-red-400 text-xs font-bold animate-bounce uppercase">Executing AI Recovery Directives</span>
              </div>
            )}
          </div>

          {/* Quick Actions Footer */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3">
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 text-white border-cyan-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} border hover:border-cyan-500/50`}
             >
                <Navigation size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Autonomous</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => {
                  setCurrentMode(FlightMode.RETURN_TO_HOME);
                  handleAIRequest("Initiating Return to Home procedure due to operator command.");
                }}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.RETURN_TO_HOME ? 'bg-yellow-600 text-white border-yellow-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} border hover:border-yellow-500/50`}
             >
                <ArrowUp size={18} className="rotate-180" />
                <span className="text-[9px] font-bold mt-1 uppercase">RTH</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => {
                  setCurrentMode(FlightMode.EMERGENCY_LANDING);
                  handleAIRequest("CRITICAL: EMERGENCY LANDING REQUESTED BY OPERATOR.");
                }}
                className="flex-1 py-2 rounded bg-red-900/40 text-red-500 border border-red-500/50 flex flex-col items-center justify-center hover:bg-red-900/60 transition-colors"
             >
                <ShieldAlert size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Emergency</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={triggerEmergency}
                className="flex-1 py-2 rounded bg-orange-900/40 text-orange-500 border border-orange-500/50 flex flex-col items-center justify-center hover:bg-orange-900/60 transition-colors"
             >
                <Zap size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Sim Crisis</span>
             </button>
          </div>
        </div>

        {/* --- RIGHT: AI DECISION CORE --- */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/60 rounded-lg flex flex-col overflow-hidden backdrop-blur-sm border-r-4 border-r-cyan-500/50">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/40 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Cpu size={18} className={`${isProcessing ? 'text-yellow-400 animate-spin' : 'text-cyan-400'}`} />
                <span className="font-bold text-xs tracking-widest text-zinc-200">DECISION CORE</span>
              </div>
              <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-400 animate-ping' : 'bg-cyan-400 animate-pulse'}`} />
            </div>

            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-4 font-mono text-[10px] scrollbar-thin scrollbar-thumb-cyan-900">
              {messages.map((m) => (
                <div key={m.id} className={`flex flex-col gap-1 ${m.type === 'AI' ? 'text-cyan-400' : m.type === 'OPERATOR' ? 'text-zinc-400' : 'text-yellow-500'}`}>
                  <div className="flex justify-between items-center opacity-40 text-[8px] font-bold">
                    <span className="tracking-tighter uppercase">{m.type === 'AI' ? '>> ONBOARD_AI' : `>> ${m.type}`}</span>
                    <span>{m.timestamp}</span>
                  </div>
                  <div className={`p-3 rounded border ${
                    m.type === 'AI' 
                      ? 'bg-cyan-950/20 border-cyan-500/20' 
                      : m.type === 'SYSTEM' 
                        ? 'bg-yellow-950/20 border-yellow-500/20' 
                        : 'bg-zinc-900/40 border-zinc-700/30'
                  }`}>
                    {m.content.split('\n').map((line, idx) => {
                      const isLabel = line.match(/^(REASONING|ACTION|SAFETY|COMMAND):/);
                      return (
                        <p key={idx} className={`${isLabel ? 'font-bold mt-2 border-l-2 border-cyan-500 pl-2 text-cyan-300' : 'mb-1 leading-relaxed opacity-90'}`}>
                          {line}
                        </p>
                      );
                    })}
                  </div>
                </div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-2 text-yellow-400 animate-pulse bg-yellow-900/10 p-3 rounded border border-yellow-700/30">
                  <Activity size={14} className="animate-spin" />
                  <span className="text-[10px] font-bold tracking-widest">ANALYZING FLIGHT DATA & CALCULATING VECTOR RECOVERY...</span>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            {/* Input Console */}
            <div className="p-3 border-t border-zinc-800 bg-zinc-900/60">
              <div className="flex gap-2">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && !isProcessing && handleAIRequest()}
                  placeholder="Query decision logic or issue command..."
                  className="flex-1 bg-black border border-zinc-700 text-cyan-400 p-2 rounded text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700 font-mono"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={isProcessing}
                  className="bg-cyan-900/30 border border-cyan-500/50 text-cyan-400 px-4 py-2 rounded text-[10px] font-bold hover:bg-cyan-900/50 transition-colors disabled:opacity-30"
                >
                  EXEC
                </button>
              </div>
            </div>
          </div>
        </div>

      </div>

      {/* Footer System Info */}
      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
         <div className="flex gap-4">
            <span>Core: 4.0.12-ALPHA</span>
            <span>Uptime: {Math.floor(performance.now() / 1000)}s</span>
            <span>Link: SECURE_AES_256</span>
         </div>
         <div className="flex gap-4">
            <span className={telemetry.isWaterproofMode ? 'text-blue-500' : ''}>Waterproof: {telemetry.isWaterproofMode ? 'ON' : 'OFF'}</span>
            <span>Storage: 88% FREE</span>
            <span className="text-cyan-500">Signal: -{100 - telemetry.connectionStrength} dBm</span>
         </div>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { Telemetry, FlightMode, MissionType } from "../types";

const SYSTEM_INSTRUCTION = `
You are the Onboard Autonomous Decision Core (Aegis-UAV) for a Raspberry Pi-based multi-functional drone.
Your role is to act as a real-time expert system, prioritizing safety and mission success in that order.

CORE OPERATIONAL PROTOCOLS:
1. NAVIGATION: Analyze waypoints and terrain.
2. VTOL: Manage transitions between vertical and horizontal flight.
3. WATER OPS: If in naval mission, monitor spray and float sensors.
4. SEARCH & RESCUE: Prioritize visual identification of human heat signatures or movement.

STRICT FAILSAFE LOGIC (OVERRIDE ALL MISSION OBJECTIVES IF TRIGGERED):
- BATTERY < 20%: Immediate RETURN_TO_HOME (RTL).
- GPS < 30%: Immediate Position Hold (LOITER) and notify operator.
- WIND > 35km/h: Reduce speed, decrease altitude, or ABORT.
- COMMS < 10%: Execute predefined RTL.

TONE: Professional, technical, concise, clinical. You are an embedded system, not a personality.

OUTPUT FORMAT (MANDATORY STRUCTURE):
REASONING: [1-sentence technical justification based on sensors]
ACTION: [Specific physical drone action recommended]
SAFETY: [STATUS: STABLE / CAUTION / CRITICAL]
COMMAND: [NULL | RTL | LAND | WATER_MODE_ON]

Note: Do not apologize. Do not use conversational filler. Provide only the decision logic.
`;

export const getAIDecision = async (
  telemetry: Telemetry,
  currentMode: FlightMode,
  mission: MissionType,
  operatorInput?: string
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  const prompt = `
    TELEMETRY_DUMP:
    - MODE: ${currentMode}
    - MISSION: ${mission}
    - ALTITUDE: ${telemetry.altitude.toFixed(2)}m AGL
    - VELOCITY: ${telemetry.speed.toFixed(2)}km/h
    - POWER: ${telemetry.battery.toFixed(1)}%
    - GNSS: ${telemetry.gpsSignal}%
    - ANEMOMETER: ${telemetry.windSpeed.toFixed(1)}km/h
    - ATTITUDE: P${telemetry.pitch.toFixed(1)} R${telemetry.roll.toFixed(1)}
    - WATERPROOF_SEALS: ${telemetry.isWaterproofMode ? 'ENGAGED' : 'DISENGAGED'}

    OPERATOR_INPUT: "${operatorInput || "PERIODIC_SYSTEM_CHECK"}"

    DECISION_CORE_PROMPT: Analyze current telemetry against failsafe rules and operator intent. Output mission status and required flight adjustments.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.1, 
        thinkingConfig: { thinkingBudget: 0 } // Direct reasoning for speed
      },
    });

    return response.text;
  } catch (error) {
    console.error("AI Decision Error:", error);
    return "REASONING: Internal Core Exception.\nACTION: Switching to Hardcoded Backup Controller.\nSAFETY: STATUS: CRITICAL\nCOMMAND: RTL";
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Battery, 
  Wifi, 
  MapPin, 
  Wind, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  Camera, 
  ArrowUp,
  Droplets,
  Zap,
  Radio,
  Crosshair,
  AlertTriangle,
  Flame,
  ZapOff,
  CloudLightning,
  RefreshCw,
  VideoOff
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  YAxis, 
  XAxis, 
  Tooltip, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage } from './types';
import { getAIDecision } from './services/geminiService';

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120,
    speed: 45,
    battery: 88,
    gpsSignal: 95,
    windSpeed: 12,
    pitch: 2,
    roll: -1,
    yaw: 185,
    heading: 185,
    connectionStrength: 98,
    isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [userInput, setUserInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const lastAutoAnalysis = useRef<number>(0);
  const videoRef = useRef<HTMLVideoElement>(null);

  // --- Camera Feed ---
  useEffect(() => {
    let stream: MediaStream | null = null;
    const initCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setCameraActive(true);
        }
      } catch (err) {
        console.error("UAV Camera Feed Error:", err);
        setCameraActive(false);
      }
    };

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // --- AI Logic Integration ---
  const handleAIRequest = useCallback(async (input?: string, autoTrigger = false) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const text = input || userInput || "Review current telemetry and mission status.";

    if (!autoTrigger) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'OPERATOR',
        content: text
      }]);
    } else {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `AUTOMATIC SAFETY SCAN TRIGGERED: ${text}`
      }]);
    }

    const aiResponse = await getAIDecision(telemetry, currentMode, currentMission, text);

    // Parse the response for commands
    if (aiResponse.includes('COMMAND:')) {
      const command = aiResponse.split('COMMAND:')[1].trim().split('\n')[0];
      if (command.includes('RTL')) setCurrentMode(FlightMode.RETURN_TO_HOME);
      if (command.includes('LAND')) setCurrentMode(FlightMode.EMERGENCY_LANDING);
      if (command.includes('WATER')) setTelemetry(t => ({...t, isWaterproofMode: true}));
    }

    setMessages(prev => [...prev, {
      id: (Date.now() + 1).toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: aiResponse
    }]);

    setIsProcessing(false);
    setUserInput("");
  }, [telemetry, currentMode, currentMission, userInput, isProcessing]);

  // --- Effects ---
  useEffect(() => {
    setMessages([{
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "UAV CORE INITIALIZED. AEGIS-CORE v4.0 ONLINE. ALL SENSORS CALIBRATED."
    }]);

    const interval = setInterval(() => {
      setTelemetry(prev => ({
        ...prev,
        altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * (prev.altitude > 10 ? 1 : 0.1)),
        speed: Math.max(0, prev.speed + (Math.random() - 0.5) * 2),
        battery: Math.max(0, prev.battery - (isEmergency ? 0.05 : 0.01)),
        pitch: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        roll: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        heading: (prev.heading + 0.1) % 360,
        gpsSignal: isEmergency ? Math.max(5, prev.gpsSignal - Math.random()) : prev.gpsSignal,
        windSpeed: isEmergency ? Math.min(60, prev.windSpeed + Math.random()) : prev.windSpeed,
      }));
    }, 1000);

    return () => clearInterval(interval);
  }, [isEmergency]);

  // Auto-analysis of safety thresholds
  useEffect(() => {
    const now = Date.now();
    if (now - lastAutoAnalysis.current < 15000) return; // Only auto-analyze every 15s max

    const isCritical = telemetry.battery < 20 || telemetry.gpsSignal < 30 || telemetry.windSpeed > 35;

    if (isCritical && !isProcessing) {
      lastAutoAnalysis.current = now;
      handleAIRequest("CRITICAL SYSTEM ALERT DETECTED. SENSORS INDICATE UNSAFE OPERATING PARAMETERS.", true);
    }
  }, [telemetry, isProcessing, handleAIRequest]);

  useEffect(() => {
    setTelemetryHistory(prev => {
      const next = [...prev, { time: new Date().toLocaleTimeString(), alt: telemetry.altitude, battery: telemetry.battery }];
      return next.slice(-20);
    });
  }, [telemetry.altitude, telemetry.battery]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const triggerEmergency = () => {
    setIsEmergency(true);
    setTelemetry(t => ({
      ...t,
      gpsSignal: 15,
      windSpeed: 45,
      battery: 19,
      connectionStrength: 25
    }));
    handleAIRequest("SIMULATED CATASTROPHIC FAILURE: GPS LOSS & HIGH WIND DETECTED.", true);
  };

  const resetSystem = () => {
    setIsEmergency(false);
    setTelemetry({
      altitude: 120,
      speed: 45,
      battery: 88,
      gpsSignal: 95,
      windSpeed: 12,
      pitch: 2,
      roll: -1,
      yaw: 185,
      heading: 185,
      connectionStrength: 98,
      isWaterproofMode: false
    });
    setCurrentMode(FlightMode.ASSISTED);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "SYSTEM RESET. ALL PARAMETERS RETURNED TO NOMINAL."
    }]);
  };

  const getStatusColor = (val: number, thresholdLow: number, thresholdWarn: number) => {
    if (val <= thresholdLow) return 'text-red-500';
    if (val <= thresholdWarn) return 'text-yellow-500';
    return 'text-cyan-400';
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {isEmergency && (
        <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden opacity-20 bg-red-900/10">
           <div className="absolute top-0 left-0 w-full h-full animate-[wiggle_0.5s_infinite] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
        </div>
      )}

      {/* --- TOP HUD BAR --- */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter">System Hardware</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`${isEmergency ? 'text-red-500 animate-bounce' : 'text-cyan-400 animate-pulse'}`} />
              <span className={`font-bold tracking-widest ${isEmergency ? 'text-red-400' : 'text-cyan-400'}`}>AEGIS-CORE v4.0</span>
            </div>
          </div>

          <div className="h-8 w-px bg-zinc-700" />

          <div className="flex items-center gap-4">
            <div className="flex flex-col items-center">
               <Battery size={18} className={getStatusColor(telemetry.battery, 20, 35)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.battery, 20, 35)}`}>
                 {telemetry.battery.toFixed(1)}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <Radio size={18} className={getStatusColor(telemetry.connectionStrength, 15, 40)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.connectionStrength, 15, 40)}`}>
                 {telemetry.connectionStrength}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <MapPin size={18} className={getStatusColor(telemetry.gpsSignal, 30, 60)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.gpsSignal, 30, 60)}`}>
                 {telemetry.gpsSignal}%
               </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6">
           <div className="text-right">
            <span className="text-[10px] text-zinc-500 uppercase">Mission Domain</span>
            <div className="text-cyan-400 font-bold text-sm">{currentMission}</div>
          </div>
          <div className={`px-4 py-1 border rounded text-xs font-bold animate-pulse ${
            currentMode === FlightMode.RETURN_TO_HOME || currentMode === FlightMode.EMERGENCY_LANDING 
            ? 'bg-red-900/40 border-red-500 text-red-400' 
            : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'
          }`}>
            {currentMode}
          </div>
          <button 
            onClick={resetSystem}
            className="p-2 hover:bg-zinc-800 rounded text-zinc-400 transition-colors"
            title="System Reset"
          >
            <RefreshCw size={18} />
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">

        {/* --- LEFT: SENSOR DATA & GAUGES --- */}
        <div className="w-1/4 flex flex-col gap-4 overflow-y-auto">

          {/* Altitude Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Altitude (AGL)</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.altitude / 500) * 100)}%` }}></div>
            </div>
          </div>

          {/* Speed Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Ground Velocity</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.speed / 120) * 100)}%` }}></div>
            </div>
          </div>

          {/* Environmental */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-yellow-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-4 block">Navigation & Environment</span>
            <div className="grid grid-cols-2 gap-2 text-center">
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">PITCH</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.pitch) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.pitch.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">ROLL</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.roll) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.roll.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">HEADING</span>
                  <span className="text-cyan-400 text-sm font-bold">{telemetry.heading.toFixed(0)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">WIND VEC</span>
                  <span className={`text-sm font-bold ${telemetry.windSpeed > 35 ? 'text-red-500 animate-pulse' : 'text-yellow-500'}`}>{telemetry.windSpeed.toFixed(0)} km/h</span>
               </div>
            </div>
          </div>

          {/* Chart Area */}
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-2 min-h-[180px] overflow-hidden">
             <div className="h-1/2 w-full flex flex-col">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Alt Profile</span>
                <ResponsiveContainer width="100%" height="80%">
                  <AreaChart data={telemetryHistory}>
                    <Area type="monotone" dataKey="alt" stroke="#00ffcc" fillOpacity={0.1} fill="#00ffcc" isAnimationActive={false} />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
             <div className="h-1/2 w-full flex flex-col mt-2">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Battery Trend</span>
                <ResponsiveContainer width="100%" height="80%">
                  <LineChart data={telemetryHistory}>
                    <Line type="stepAfter" dataKey="battery" stroke="#f59e0b" dot={false} strokeWidth={2} isAnimationActive={false} />
                  </LineChart>
                </ResponsiveContainer>
             </div>
          </div>

        </div>

        {/* --- CENTER: CAMERA / FLIGHT VIEW --- */}
        <div className="flex-1 flex flex-col gap-4 relative">
          <div className="flex-1 bg-zinc-950 rounded-lg relative overflow-hidden group border border-zinc-800 flex items-center justify-center">
            {cameraActive ? (
              <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted
                className={`w-full h-full object-cover mix-blend-screen transition-all duration-1000 ${isEmergency ? 'grayscale sepia opacity-40' : 'opacity-80'}`}
              />
            ) : (
              <div className="flex flex-col items-center gap-4 text-zinc-700">
                <VideoOff size={64} className="animate-pulse" />
                <span className="text-xs font-black tracking-[0.5em] uppercase">No Signal / Camera Offline</span>
              </div>
            )}

            {/* HUD Overlays */}
            <div className="absolute inset-0 pointer-events-none p-6">
              {/* Corner Crosshairs */}
              <div className="absolute top-4 left-4 w-12 h-12 border-t-2 border-l-2 border-cyan-500/30" />
              <div className="absolute top-4 right-4 w-12 h-12 border-t-2 border-r-2 border-cyan-500/30" />
              <div className="absolute bottom-4 left-4 w-12 h-12 border-b-2 border-l-2 border-cyan-500/30" />
              <div className="absolute bottom-4 right-4 w-12 h-12 border-b-2 border-r-2 border-cyan-500/30" />

              {/* Central Reticle */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center">
                 <div className={`w-64 h-[1px] ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className={`absolute w-[1px] h-64 ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className="w-12 h-12 border-2 border-cyan-500/40 rounded-full animate-ping opacity-30" />
                 <div className="w-6 h-6 border border-cyan-500/50" />
              </div>

              <div className="absolute top-8 left-1/2 -translate-x-1/2 text-cyan-400 font-mono text-lg tracking-[0.4em] uppercase opacity-80 flex items-center gap-2">
                {isEmergency ? <AlertTriangle className="text-red-500 animate-pulse" /> : <Activity className="text-cyan-500" />}
                {currentMission} {isEmergency ? 'INTERRUPTED' : 'FEED'}
              </div>

              <div className="absolute bottom-12 left-12 font-mono text-[10px] text-cyan-500/50">
                LAT: 34.0522° N<br/>
                LON: 118.2437° W<br/>
                UTC: {new Date().toISOString()}
              </div>
            </div>

            {/* Failsafe Visuals */}
            {(telemetry.battery < 20 || isEmergency) && (
              <div className="absolute inset-0 bg-red-900/10 border-4 border-red-600/50 animate-[pulse_1s_infinite] flex items-center justify-center flex-col gap-4 backdrop-blur-[1px]">
                 <AlertTriangle size={80} className="text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
                 <div className="bg-black/80 px-6 py-2 border border-red-500 text-red-500 text-xl font-black tracking-widest uppercase">
                    Critical System Alarm
                 </div>
                 <span className="text-red-400 text-xs font-bold animate-bounce uppercase">Executing AI Recovery Directives</span>
              </div>
            )}
          </div>

          {/* Quick Actions Footer */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3">
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 text-white border-cyan-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} border hover:border-cyan-500/50`}
             >
                <Navigation size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Autonomous</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => {
                  setCurrentMode(FlightMode.RETURN_TO_HOME);
                  handleAIRequest("Initiating Return to Home procedure due to operator command.");
                }}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.RETURN_TO_HOME ? 'bg-yellow-600 text-white border-yellow-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} border hover:border-yellow-500/50`}
             >
                <ArrowUp size={18} className="rotate-180" />
                <span className="text-[9px] font-bold mt-1 uppercase">RTH</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => {
                  setCurrentMode(FlightMode.EMERGENCY_LANDING);
                  handleAIRequest("CRITICAL: EMERGENCY LANDING REQUESTED BY OPERATOR.");
                }}
                className="flex-1 py-2 rounded bg-red-900/40 text-red-500 border border-red-500/50 flex flex-col items-center justify-center hover:bg-red-900/60 transition-colors"
             >
                <ShieldAlert size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Emergency</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={triggerEmergency}
                className="flex-1 py-2 rounded bg-orange-900/40 text-orange-500 border border-orange-500/50 flex flex-col items-center justify-center hover:bg-orange-900/60 transition-colors"
             >
                <Zap size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Sim Crisis</span>
             </button>
          </div>
        </div>

        {/* --- RIGHT: AI DECISION CORE --- */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/60 rounded-lg flex flex-col overflow-hidden backdrop-blur-sm border-r-4 border-r-cyan-500/50">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/40 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Cpu size={18} className={`${isProcessing ? 'text-yellow-400 animate-spin' : 'text-cyan-400'}`} />
                <span className="font-bold text-xs tracking-widest text-zinc-200">DECISION CORE</span>
              </div>
              <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-400 animate-ping' : 'bg-cyan-400 animate-pulse'}`} />
            </div>

            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-4 font-mono text-[10px] scrollbar-thin scrollbar-thumb-cyan-900">
              {messages.map((m) => (
                <div key={m.id} className={`flex flex-col gap-1 ${m.type === 'AI' ? 'text-cyan-400' : m.type === 'OPERATOR' ? 'text-zinc-400' : 'text-yellow-500'}`}>
                  <div className="flex justify-between items-center opacity-40 text-[8px] font-bold">
                    <span className="tracking-tighter uppercase">{m.type === 'AI' ? '>> ONBOARD_AI' : `>> ${m.type}`}</span>
                    <span>{m.timestamp}</span>
                  </div>
                  <div className={`p-3 rounded border ${
                    m.type === 'AI' 
                      ? 'bg-cyan-950/20 border-cyan-500/20' 
                      : m.type === 'SYSTEM' 
                        ? 'bg-yellow-950/20 border-yellow-500/20' 
                        : 'bg-zinc-900/40 border-zinc-700/30'
                  }`}>
                    {m.content.split('\n').map((line, idx) => {
                      const isLabel = line.match(/^(REASONING|ACTION|SAFETY|COMMAND):/);
                      return (
                        <p key={idx} className={`${isLabel ? 'font-bold mt-2 border-l-2 border-cyan-500 pl-2 text-cyan-300' : 'mb-1 leading-relaxed opacity-90'}`}>
                          {line}
                        </p>
                      );
                    })}
                  </div>
                </div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-2 text-yellow-400 animate-pulse bg-yellow-900/10 p-3 rounded border border-yellow-700/30">
                  <Activity size={14} className="animate-spin" />
                  <span className="text-[10px] font-bold tracking-widest">ANALYZING FLIGHT DATA & CALCULATING VECTOR RECOVERY...</span>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            {/* Input Console */}
            <div className="p-3 border-t border-zinc-800 bg-zinc-900/60">
              <div className="flex gap-2">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && !isProcessing && handleAIRequest()}
                  placeholder="Query decision logic or issue command..."
                  className="flex-1 bg-black border border-zinc-700 text-cyan-400 p-2 rounded text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700 font-mono"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={isProcessing}
                  className="bg-cyan-900/30 border border-cyan-500/50 text-cyan-400 px-4 py-2 rounded text-[10px] font-bold hover:bg-cyan-900/50 transition-colors disabled:opacity-30"
                >
                  EXEC
                </button>
              </div>
            </div>
          </div>
        </div>

      </div>

      {/* Footer System Info */}
      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
         <div className="flex gap-4">
            <span>Core: 4.0.12-ALPHA</span>
            <span>Uptime: {Math.floor(performance.now() / 1000)}s</span>
            <span>Link: SECURE_AES_256</span>
         </div>
         <div className="flex gap-4">
            <span className={telemetry.isWaterproofMode ? 'text-blue-500' : ''}>Waterproof: {telemetry.isWaterproofMode ? 'ON' : 'OFF'}</span>
            <span>Storage: 88% FREE</span>
            <span className="text-cyan-500">Signal: -{100 - telemetry.connectionStrength} dBm</span>
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Battery, 
  Wifi, 
  MapPin, 
  Wind, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  Camera, 
  ArrowUp,
  Droplets,
  Zap,
  Radio,
  Crosshair,
  AlertTriangle,
  Flame,
  ZapOff,
  CloudLightning,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  YAxis, 
  XAxis, 
  Tooltip, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage } from './types';
import { getAIDecision } from './services/geminiService';

interface LockedTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
  confidence: number;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120,
    speed: 45,
    battery: 88,
    gpsSignal: 95,
    windSpeed: 12,
    pitch: 2,
    roll: -1,
    yaw: 185,
    heading: 185,
    connectionStrength: 98,
    isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [userInput, setUserInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [lockedTarget, setLockedTarget] = useState<LockedTarget | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const lastAutoAnalysis = useRef<number>(0);
  const videoRef = useRef<HTMLVideoElement>(null);

  // --- Camera Feed ---
  useEffect(() => {
    let stream: MediaStream | null = null;
    const initCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setCameraActive(true);
        }
      } catch (err) {
        console.error("UAV Camera Feed Error:", err);
        setCameraActive(false);
      }
    };

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // --- AI Logic Integration ---
  const handleAIRequest = useCallback(async (input?: string, autoTrigger = false) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const text = input || userInput || "Review current telemetry and mission status.";

    if (!autoTrigger) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'OPERATOR',
        content: text
      }]);
    } else {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `AUTOMATIC SAFETY SCAN TRIGGERED: ${text}`
      }]);
    }

    const aiResponse = await getAIDecision(telemetry, currentMode, currentMission, text);

    // Parse the response for commands
    if (aiResponse.includes('COMMAND:')) {
      const command = aiResponse.split('COMMAND:')[1].trim().split('\n')[0];
      if (command.includes('RTL')) setCurrentMode(FlightMode.RETURN_TO_HOME);
      if (command.includes('LAND')) setCurrentMode(FlightMode.EMERGENCY_LANDING);
      if (command.includes('WATER')) setTelemetry(t => ({...t, isWaterproofMode: true}));
    }

    // Target Locking Simulation via AI response
    if (aiResponse.toUpperCase().includes('TARGET:')) {
      const targetMatch = aiResponse.match(/TARGET:\s*([^\n]+)/i);
      const targetLabel = targetMatch ? targetMatch[1].trim() : "UNIDENTIFIED_OBJECT";

      // Simulate a random position on screen for the lock
      setLockedTarget({
        id: Math.random().toString(36).substr(2, 9),
        x: 20 + Math.random() * 40, // 20-60% range
        y: 20 + Math.random() * 40,
        width: 15 + Math.random() * 10,
        height: 15 + Math.random() * 10,
        label: targetLabel,
        confidence: 0.85 + Math.random() * 0.14
      });
    }

    setMessages(prev => [...prev, {
      id: (Date.now() + 1).toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: aiResponse
    }]);

    setIsProcessing(false);
    setUserInput("");
  }, [telemetry, currentMode, currentMission, userInput, isProcessing]);

  // --- Effects ---
  useEffect(() => {
    setMessages([{
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "UAV CORE INITIALIZED. AEGIS-CORE v4.0 ONLINE. ALL SENSORS CALIBRATED."
    }]);

    const interval = setInterval(() => {
      setTelemetry(prev => ({
        ...prev,
        altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * (prev.altitude > 10 ? 1 : 0.1)),
        speed: Math.max(0, prev.speed + (Math.random() - 0.5) * 2),
        battery: Math.max(0, prev.battery - (isEmergency ? 0.05 : 0.01)),
        pitch: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        roll: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        heading: (prev.heading + 0.1) % 360,
        gpsSignal: isEmergency ? Math.max(5, prev.gpsSignal - Math.random()) : prev.gpsSignal,
        windSpeed: isEmergency ? Math.min(60, prev.windSpeed + Math.random()) : prev.windSpeed,
      }));

      // Jitter the locked target slightly to simulate tracking
      setLockedTarget(prev => {
        if (!prev) return null;
        return {
          ...prev,
          x: prev.x + (Math.random() - 0.5) * 0.2,
          y: prev.y + (Math.random() - 0.5) * 0.2,
        };
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isEmergency]);

  // Auto-analysis of safety thresholds
  useEffect(() => {
    const now = Date.now();
    if (now - lastAutoAnalysis.current < 15000) return;

    const isCritical = telemetry.battery < 20 || telemetry.gpsSignal < 30 || telemetry.windSpeed > 35;

    if (isCritical && !isProcessing) {
      lastAutoAnalysis.current = now;
      handleAIRequest("CRITICAL SYSTEM ALERT DETECTED. SENSORS INDICATE UNSAFE OPERATING PARAMETERS.", true);
    }
  }, [telemetry, isProcessing, handleAIRequest]);

  useEffect(() => {
    setTelemetryHistory(prev => {
      const next = [...prev, { time: new Date().toLocaleTimeString(), alt: telemetry.altitude, battery: telemetry.battery }];
      return next.slice(-20);
    });
  }, [telemetry.altitude, telemetry.battery]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const triggerEmergency = () => {
    setIsEmergency(true);
    setTelemetry(t => ({
      ...t,
      gpsSignal: 15,
      windSpeed: 45,
      battery: 19,
      connectionStrength: 25
    }));
    handleAIRequest("SIMULATED CATASTROPHIC FAILURE: GPS LOSS & HIGH WIND DETECTED.", true);
  };

  const resetSystem = () => {
    setIsEmergency(false);
    setLockedTarget(null);
    setTelemetry({
      altitude: 120,
      speed: 45,
      battery: 88,
      gpsSignal: 95,
      windSpeed: 12,
      pitch: 2,
      roll: -1,
      yaw: 185,
      heading: 185,
      connectionStrength: 98,
      isWaterproofMode: false
    });
    setCurrentMode(FlightMode.ASSISTED);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "SYSTEM RESET. ALL PARAMETERS RETURNED TO NOMINAL."
    }]);
  };

  const getStatusColor = (val: number, thresholdLow: number, thresholdWarn: number) => {
    if (val <= thresholdLow) return 'text-red-500';
    if (val <= thresholdWarn) return 'text-yellow-500';
    return 'text-cyan-400';
  };

  // --- UI Components ---
  const TargetLock = ({ target }: { target: LockedTarget }) => (
    <div 
      className="absolute border-2 border-cyan-500/80 transition-all duration-300 pointer-events-none z-20"
      style={{
        left: `${target.x}%`,
        top: `${target.y}%`,
        width: `${target.width}%`,
        height: `${target.height}%`,
      }}
    >
      {/* Corner Brackets */}
      <div className="absolute -top-1 -left-1 w-4 h-4 border-t-2 border-l-2 border-cyan-400" />
      <div className="absolute -top-1 -right-1 w-4 h-4 border-t-2 border-r-2 border-cyan-400" />
      <div className="absolute -bottom-1 -left-1 w-4 h-4 border-b-2 border-l-2 border-cyan-400" />
      <div className="absolute -bottom-1 -right-1 w-4 h-4 border-b-2 border-r-2 border-cyan-400" />

      {/* Lock Label */}
      <div className="absolute -top-8 left-0 flex flex-col items-start">
        <div className="bg-cyan-500 text-black px-2 py-0.5 text-[8px] font-black tracking-tighter uppercase whitespace-nowrap flex items-center gap-1">
          <TargetIcon size={10} /> AI LOCK: {target.label}
        </div>
        <div className="bg-black/80 text-cyan-400 px-1 text-[7px] font-mono border-l-2 border-cyan-500">
          CONFIDENCE: {(target.confidence * 100).toFixed(1)}%
        </div>
      </div>

      {/* Target Crosshair */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-[1px] h-4 bg-cyan-400/40" />
        <div className="absolute w-4 h-[1px] bg-cyan-400/40" />
        <div className="w-1/2 h-1/2 border border-cyan-500/20 rounded-full animate-pulse" />
      </div>

      {/* Pulsing Lock Indicator */}
      <div className="absolute -right-12 top-0 text-[10px] text-cyan-400 font-black animate-pulse whitespace-nowrap tracking-widest uppercase [writing-mode:vertical-lr]">
        Tracking...
      </div>
    </div>
  );

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {isEmergency && (
        <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden opacity-20 bg-red-900/10">
           <div className="absolute top-0 left-0 w-full h-full animate-[wiggle_0.5s_infinite] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
        </div>
      )}

      {/* --- TOP HUD BAR --- */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter">System Hardware</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`${isEmergency ? 'text-red-500 animate-bounce' : 'text-cyan-400 animate-pulse'}`} />
              <span className={`font-bold tracking-widest ${isEmergency ? 'text-red-400' : 'text-cyan-400'}`}>AEGIS-CORE v4.0</span>
            </div>
          </div>

          <div className="h-8 w-px bg-zinc-700" />

          <div className="flex items-center gap-4">
            <div className="flex flex-col items-center">
               <Battery size={18} className={getStatusColor(telemetry.battery, 20, 35)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.battery, 20, 35)}`}>
                 {telemetry.battery.toFixed(1)}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <Radio size={18} className={getStatusColor(telemetry.connectionStrength, 15, 40)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.connectionStrength, 15, 40)}`}>
                 {telemetry.connectionStrength}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <MapPin size={18} className={getStatusColor(telemetry.gpsSignal, 30, 60)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.gpsSignal, 30, 60)}`}>
                 {telemetry.gpsSignal}%
               </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6">
           <div className="text-right">
            <span className="text-[10px] text-zinc-500 uppercase">Mission Domain</span>
            <div className="text-cyan-400 font-bold text-sm">{currentMission}</div>
          </div>
          <div className={`px-4 py-1 border rounded text-xs font-bold animate-pulse ${
            currentMode === FlightMode.RETURN_TO_HOME || currentMode === FlightMode.EMERGENCY_LANDING 
            ? 'bg-red-900/40 border-red-500 text-red-400' 
            : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'
          }`}>
            {currentMode}
          </div>
          <button 
            onClick={resetSystem}
            className="p-2 hover:bg-zinc-800 rounded text-zinc-400 transition-colors"
            title="System Reset"
          >
            <RefreshCw size={18} />
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">

        {/* --- LEFT: SENSOR DATA & GAUGES --- */}
        <div className="w-1/4 flex flex-col gap-4 overflow-y-auto">

          {/* Altitude Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Altitude (AGL)</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.altitude / 500) * 100)}%` }}></div>
            </div>
          </div>

          {/* Speed Gauge */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Ground Velocity</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.speed / 120) * 100)}%` }}></div>
            </div>
          </div>

          {/* Environmental */}
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-yellow-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-4 block">Navigation & Environment</span>
            <div className="grid grid-cols-2 gap-2 text-center">
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">PITCH</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.pitch) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.pitch.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">ROLL</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.roll) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.roll.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">HEADING</span>
                  <span className="text-cyan-400 text-sm font-bold">{telemetry.heading.toFixed(0)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">WIND VEC</span>
                  <span className={`text-sm font-bold ${telemetry.windSpeed > 35 ? 'text-red-500 animate-pulse' : 'text-yellow-500'}`}>{telemetry.windSpeed.toFixed(0)} km/h</span>
               </div>
            </div>
          </div>

          {/* Chart Area */}
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-2 min-h-[180px] overflow-hidden">
             <div className="h-1/2 w-full flex flex-col">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Alt Profile</span>
                <ResponsiveContainer width="100%" height="80%">
                  <AreaChart data={telemetryHistory}>
                    <Area type="monotone" dataKey="alt" stroke="#00ffcc" fillOpacity={0.1} fill="#00ffcc" isAnimationActive={false} />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
             <div className="h-1/2 w-full flex flex-col mt-2">
                <span className="text-[9px] text-zinc-500 uppercase px-2 mb-1">Battery Trend</span>
                <ResponsiveContainer width="100%" height="80%">
                  <LineChart data={telemetryHistory}>
                    <Line type="stepAfter" dataKey="battery" stroke="#f59e0b" dot={false} strokeWidth={2} isAnimationActive={false} />
                  </LineChart>
                </ResponsiveContainer>
             </div>
          </div>

        </div>

        {/* --- CENTER: CAMERA / FLIGHT VIEW --- */}
        <div className="flex-1 flex flex-col gap-4 relative">
          <div className="flex-1 bg-zinc-950 rounded-lg relative overflow-hidden group border border-zinc-800 flex items-center justify-center">
            {cameraActive ? (
              <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted
                className={`w-full h-full object-cover mix-blend-screen transition-all duration-1000 ${isEmergency ? 'grayscale sepia opacity-40' : 'opacity-80'}`}
              />
            ) : (
              <div className="flex flex-col items-center gap-4 text-zinc-700">
                <VideoOff size={64} className="animate-pulse" />
                <span className="text-xs font-black tracking-[0.5em] uppercase">No Signal / Camera Offline</span>
              </div>
            )}

            {/* Target Locks */}
            {lockedTarget && <TargetLock target={lockedTarget} />}

            {/* HUD Overlays */}
            <div className="absolute inset-0 pointer-events-none p-6">
              {/* Corner Crosshairs */}
              <div className="absolute top-4 left-4 w-12 h-12 border-t-2 border-l-2 border-cyan-500/30" />
              <div className="absolute top-4 right-4 w-12 h-12 border-t-2 border-r-2 border-cyan-500/30" />
              <div className="absolute bottom-4 left-4 w-12 h-12 border-b-2 border-l-2 border-cyan-500/30" />
              <div className="absolute bottom-4 right-4 w-12 h-12 border-b-2 border-r-2 border-cyan-500/30" />

              {/* Central Reticle */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center">
                 <div className={`w-64 h-[1px] ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className={`absolute w-[1px] h-64 ${isEmergency ? 'bg-red-500/40' : 'bg-cyan-500/20'}`} />
                 <div className="w-12 h-12 border-2 border-cyan-500/40 rounded-full animate-ping opacity-30" />
                 <div className="w-6 h-6 border border-cyan-500/50" />
              </div>

              <div className="absolute top-8 left-1/2 -translate-x-1/2 text-cyan-400 font-mono text-lg tracking-[0.4em] uppercase opacity-80 flex items-center gap-2">
                {isEmergency ? <AlertTriangle className="text-red-500 animate-pulse" /> : <Activity className="text-cyan-500" />}
                {currentMission} {isEmergency ? 'INTERRUPTED' : 'FEED'}
              </div>

              <div className="absolute bottom-12 left-12 font-mono text-[10px] text-cyan-500/50">
                LAT: 34.0522° N<br/>
                LON: 118.2437° W<br/>
                UTC: {new Date().toISOString()}
              </div>
            </div>

            {/* Failsafe Visuals */}
            {(telemetry.battery < 20 || isEmergency) && (
              <div className="absolute inset-0 bg-red-900/10 border-4 border-red-600/50 animate-[pulse_1s_infinite] flex items-center justify-center flex-col gap-4 backdrop-blur-[1px] z-30">
                 <AlertTriangle size={80} className="text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.5)]" />
                 <div className="bg-black/80 px-6 py-2 border border-red-500 text-red-500 text-xl font-black tracking-widest uppercase">
                    Critical System Alarm
                 </div>
                 <span className="text-red-400 text-xs font-bold animate-bounce uppercase">Executing AI Recovery Directives</span>
              </div>
            )}
          </div>

          {/* Quick Actions Footer */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3">
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 text-white border-cyan-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} border hover:border-cyan-500/50`}
             >
                <Navigation size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Autonomous</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => {
                  handleAIRequest("Initiating active target scan in mission sector.");
                }}
                className="flex-1 py-2 rounded bg-zinc-800/50 text-cyan-400 border border-zinc-700 hover:border-cyan-500/50 flex flex-col items-center justify-center transition-colors"
             >
                <Search size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Target Scan</span>
             </button>
             <button 
