            <span className="text-cyan-500">Signal: -{100 - telemetry.connectionStrength} dBm</span>
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { 
  Battery, 
  Wifi, 
  MapPin, 
  Wind, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  Camera, 
  ArrowUp,
  Droplets,
  Zap,
  Radio,
  Crosshair,
  AlertTriangle,
  Flame,
  ZapOff,
  CloudLightning,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search,
  Info,
  ShieldCheck,
  PlayCircle,
  PauseCircle,
  Terminal
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  YAxis, 
  XAxis, 
  Tooltip, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage } from './types';
import { getAIDecision } from './services/geminiService';

interface LockedTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
  confidence: number;
}

interface RiskAssessment {
  level: 'NORMAL' | 'CAUTION' | 'CRITICAL';
  suggestion: string;
  icon: React.ReactNode;
  confidence: number;
  executableAction: 'RTL' | 'ALTITUDE' | 'SPEED' | 'HOLD' | 'NONE';
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120,
    speed: 45,
    battery: 88,
    gpsSignal: 95,
    windSpeed: 12,
    pitch: 2,
    roll: -1,
    yaw: 185,
    heading: 185,
    connectionStrength: 98,
    isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [userInput, setUserInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [lockedTarget, setLockedTarget] = useState<LockedTarget | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const lastAutoAnalysis = useRef<number>(0);
  const videoRef = useRef<HTMLVideoElement>(null);

  // --- Real-time Risk Assessment Logic ---
  const riskAssessment = useMemo((): RiskAssessment => {
    if (!telemetry || (isEmergency && telemetry.gpsSignal < 5)) {
      return { 
        level: 'CRITICAL', 
        suggestion: 'AI STATUS: Limited data – Operator attention required.', 
        icon: <AlertTriangle size={14} />,
        confidence: 0.1,
        executableAction: 'NONE'
      };
    }

    const issues: string[] = [];
    let level: 'NORMAL' | 'CAUTION' | 'CRITICAL' = 'NORMAL';
    let action: 'RTL' | 'ALTITUDE' | 'SPEED' | 'HOLD' | 'NONE' = 'NONE';
    let confidence = 0.95;

    if (telemetry.battery < 20) {
      level = 'CRITICAL';
      issues.push("CRITICAL BATTERY: RETURN TO HOME IMMEDIATELY");
      action = 'RTL';
      confidence = 0.99;
    } else if (telemetry.battery < 35) {
      level = 'CAUTION';
      issues.push("LOW POWER: MONITOR LANDING SITES");
      action = 'HOLD';
      confidence = 0.8;
    }

    if (telemetry.gpsSignal < 30) {
      level = 'CRITICAL';
      issues.push("GPS LOSS: HOLD POSITION / MANUAL OVERRIDE");
      action = 'HOLD';
      confidence = 0.45; // Hard to be confident with no GPS
    } else if (telemetry.gpsSignal < 60) {
      level = level === 'CRITICAL' ? 'CRITICAL' : 'CAUTION';
      issues.push("WEAK GPS: AVOID TIGHT MANEUVERS");
      action = 'HOLD';
      confidence = 0.7;
    }

    if (telemetry.windSpeed > 45) {
      level = 'CRITICAL';
      issues.push("EXTREME WIND: ABORT MISSION");
      action = 'RTL';
      confidence = 0.9;
    } else if (telemetry.windSpeed > 30) {
      level = level === 'CRITICAL' ? 'CRITICAL' : 'CAUTION';
      issues.push("HIGH WIND: REDUCE ALTITUDE");
      action = 'ALTITUDE';
      confidence = 0.85;
    }

    if (telemetry.altitude > 400) {
      level = level === 'CRITICAL' ? 'CRITICAL' : 'CAUTION';
      issues.push("ALTITUDE LIMIT: REDUCE HEIGHT");
      action = 'ALTITUDE';
      confidence = 0.95;
    }

    if (level === 'NORMAL') {
      return { 
        level: 'NORMAL', 
        suggestion: 'SYSTEM NOMINAL: MISSION PARAMETERS WITHIN TOLERANCE', 
        icon: <ShieldCheck size={14} className="text-cyan-400" />,
        confidence: 0.98,
        executableAction: 'NONE'
      };
    }

    return {
      level,
      suggestion: issues[0],
      icon: level === 'CRITICAL' ? <AlertTriangle size={14} className="animate-pulse" /> : <Info size={14} />,
      confidence,
      executableAction: action
    };
  }, [telemetry, isEmergency]);

  // --- Suggestion Execution Handler ---
  const handleFollowSuggestion = useCallback(async () => {
    if (riskAssessment.executableAction === 'NONE' || riskAssessment.confidence < 0.4) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: "ACTION BLOCKED – INSUFFICIENT DATA OR LOW CONFIDENCE."
      }]);
      return;
    }

    setIsExecutingSuggestion(true);

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "AI WILL EXECUTE RECOMMENDED SAFE MANEUVER: " + riskAssessment.executableAction
    }]);

    // Artificial delay for "Execution"
    await new Promise(resolve => setTimeout(resolve, 2000));

    // Fallback Simulation (10% chance of failure if confidence is not perfect)
    if (Math.random() > riskAssessment.confidence + 0.1) {
      setIsExecutingSuggestion(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: "AI EXECUTION ABORTED – MANUAL CONTROL RESTORED."
      }]);
      return;
    }

    // Execute Actions
    switch (riskAssessment.executableAction) {
      case 'RTL':
        setCurrentMode(FlightMode.RETURN_TO_HOME);
        break;
      case 'ALTITUDE':
        setTelemetry(prev => ({ ...prev, altitude: Math.max(10, prev.altitude - 50) }));
        break;
      case 'SPEED':
        setTelemetry(prev => ({ ...prev, speed: Math.max(0, prev.speed - 20) }));
        break;
      case 'HOLD':
        setCurrentMode(FlightMode.ASSISTED);
        break;
    }

    setIsExecutingSuggestion(false);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `MANEUVER [${riskAssessment.executableAction}] COMPLETED SUCCESSFULLY. PARAMETERS STABILIZING.`
    }]);
  }, [riskAssessment]);

  // --- Camera Feed ---
  useEffect(() => {
    let stream: MediaStream | null = null;
    const initCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { width: 1280, height: 720 } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setCameraActive(true);
        }
      } catch (err) {
        console.error("UAV Camera Feed Error:", err);
        setCameraActive(false);
      }
    };

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // --- AI Logic Integration ---
  const handleAIRequest = useCallback(async (input?: string, autoTrigger = false) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const text = input || userInput || "Review current telemetry and mission status.";

    if (!autoTrigger) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'OPERATOR',
        content: text
      }]);
    } else {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `AUTOMATIC SAFETY SCAN TRIGGERED: ${text}`
      }]);
    }

    const aiResponse = await getAIDecision(telemetry, currentMode, currentMission, text);

    if (aiResponse.includes('COMMAND:')) {
      const command = aiResponse.split('COMMAND:')[1].trim().split('\n')[0];
      if (command.includes('RTL')) setCurrentMode(FlightMode.RETURN_TO_HOME);
      if (command.includes('LAND')) setCurrentMode(FlightMode.EMERGENCY_LANDING);
      if (command.includes('WATER')) setTelemetry(t => ({...t, isWaterproofMode: true}));
    }

    if (aiResponse.toUpperCase().includes('TARGET:')) {
      const targetMatch = aiResponse.match(/TARGET:\s*([^\n]+)/i);
      const targetLabel = targetMatch ? targetMatch[1].trim() : "UNIDENTIFIED_OBJECT";

      setLockedTarget({
        id: Math.random().toString(36).substr(2, 9),
        x: 20 + Math.random() * 40,
        y: 20 + Math.random() * 40,
        width: 15 + Math.random() * 10,
        height: 15 + Math.random() * 10,
        label: targetLabel,
        confidence: 0.85 + Math.random() * 0.14
      });
    }

    setMessages(prev => [...prev, {
      id: (Date.now() + 1).toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: aiResponse
    }]);

    setIsProcessing(false);
    setUserInput("");
  }, [telemetry, currentMode, currentMission, userInput, isProcessing]);

  // --- Effects ---
  useEffect(() => {
    setMessages([{
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "UAV CORE INITIALIZED. AEGIS-CORE v4.0 ONLINE. ALL SENSORS CALIBRATED."
    }]);

    const interval = setInterval(() => {
      setTelemetry(prev => ({
        ...prev,
        altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * (prev.altitude > 10 ? 1 : 0.1)),
        speed: Math.max(0, prev.speed + (Math.random() - 0.5) * 2),
        battery: Math.max(0, prev.battery - (isEmergency ? 0.05 : 0.01)),
        pitch: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        roll: (Math.random() - 0.5) * (isEmergency ? 15 : 4),
        heading: (prev.heading + 0.1) % 360,
        gpsSignal: isEmergency ? Math.max(5, prev.gpsSignal - Math.random()) : prev.gpsSignal,
        windSpeed: isEmergency ? Math.min(60, prev.windSpeed + Math.random()) : prev.windSpeed,
        connectionStrength: isEmergency ? Math.max(10, prev.connectionStrength - Math.random()) : prev.connectionStrength
      }));

      setLockedTarget(prev => {
        if (!prev) return null;
        return {
          ...prev,
          x: prev.x + (Math.random() - 0.5) * 0.2,
          y: prev.y + (Math.random() - 0.5) * 0.2,
        };
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isEmergency]);

  useEffect(() => {
    const now = Date.now();
    if (now - lastAutoAnalysis.current < 15000) return;

    const isCritical = telemetry.battery < 20 || telemetry.gpsSignal < 30 || telemetry.windSpeed > 35;

    if (isCritical && !isProcessing) {
      lastAutoAnalysis.current = now;
      handleAIRequest("CRITICAL SYSTEM ALERT DETECTED. SENSORS INDICATE UNSAFE OPERATING PARAMETERS.", true);
    }
  }, [telemetry, isProcessing, handleAIRequest]);

  useEffect(() => {
    setTelemetryHistory(prev => {
      const next = [...prev, { time: new Date().toLocaleTimeString(), alt: telemetry.altitude, battery: telemetry.battery }];
      return next.slice(-20);
    });
  }, [telemetry.altitude, telemetry.battery]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const triggerEmergency = () => {
    setIsEmergency(true);
    setTelemetry(t => ({
      ...t,
      gpsSignal: 15,
      windSpeed: 45,
      battery: 19,
      connectionStrength: 25
    }));
    handleAIRequest("SIMULATED CATASTROPHIC FAILURE: GPS LOSS & HIGH WIND DETECTED.", true);
  };

  const resetSystem = () => {
    setIsEmergency(false);
    setIsExecutingSuggestion(false);
    setLockedTarget(null);
    setTelemetry({
      altitude: 120,
      speed: 45,
      battery: 88,
      gpsSignal: 95,
      windSpeed: 12,
      pitch: 2,
      roll: -1,
      yaw: 185,
      heading: 185,
      connectionStrength: 98,
      isWaterproofMode: false
    });
    setCurrentMode(FlightMode.ASSISTED);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "SYSTEM RESET. ALL PARAMETERS RETURNED TO NOMINAL."
    }]);
  };

  const getStatusColor = (val: number, thresholdLow: number, thresholdWarn: number) => {
    if (val <= thresholdLow) return 'text-red-500';
    if (val <= thresholdWarn) return 'text-yellow-500';
    return 'text-cyan-400';
  };

  // --- UI Components ---
  const TargetLock = ({ target }: { target: LockedTarget }) => (
    <div 
      className="absolute border-2 border-cyan-500/80 transition-all duration-300 pointer-events-none z-20"
      style={{
        left: `${target.x}%`,
        top: `${target.y}%`,
        width: `${target.width}%`,
        height: `${target.height}%`,
      }}
    >
      <div className="absolute -top-1 -left-1 w-4 h-4 border-t-2 border-l-2 border-cyan-400" />
      <div className="absolute -top-1 -right-1 w-4 h-4 border-t-2 border-r-2 border-cyan-400" />
      <div className="absolute -bottom-1 -left-1 w-4 h-4 border-b-2 border-l-2 border-cyan-400" />
      <div className="absolute -bottom-1 -right-1 w-4 h-4 border-b-2 border-r-2 border-cyan-400" />

      <div className="absolute -top-8 left-0 flex flex-col items-start">
        <div className="bg-cyan-500 text-black px-2 py-0.5 text-[8px] font-black tracking-tighter uppercase whitespace-nowrap flex items-center gap-1">
          <TargetIcon size={10} /> AI LOCK: {target.label}
        </div>
        <div className="bg-black/80 text-cyan-400 px-1 text-[7px] font-mono border-l-2 border-cyan-500">
          CONFIDENCE: {(target.confidence * 100).toFixed(1)}%
        </div>
      </div>

      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-[1px] h-4 bg-cyan-400/40" />
        <div className="absolute w-4 h-[1px] bg-cyan-400/40" />
        <div className="w-1/2 h-1/2 border border-cyan-500/20 rounded-full animate-pulse" />
      </div>

      <div className="absolute -right-12 top-0 text-[10px] text-cyan-400 font-black animate-pulse whitespace-nowrap tracking-widest uppercase [writing-mode:vertical-lr]">
        Tracking...
      </div>
    </div>
  );

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {isEmergency && (
        <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden opacity-20 bg-red-900/10">
           <div className="absolute top-0 left-0 w-full h-full animate-[wiggle_0.5s_infinite] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
        </div>
      )}

      {/* --- TOP HUD BAR --- */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter">System Hardware</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`${isEmergency ? 'text-red-500 animate-bounce' : 'text-cyan-400 animate-pulse'}`} />
              <span className={`font-bold tracking-widest ${isEmergency ? 'text-red-400' : 'text-cyan-400'}`}>AEGIS-CORE v4.0</span>
            </div>
          </div>

          <div className="h-8 w-px bg-zinc-700" />

          <div className="flex items-center gap-4">
            <div className="flex flex-col items-center">
               <Battery size={18} className={getStatusColor(telemetry.battery, 20, 35)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.battery, 20, 35)}`}>
                 {telemetry.battery.toFixed(1)}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <Radio size={18} className={getStatusColor(telemetry.connectionStrength, 15, 40)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.connectionStrength, 15, 40)}`}>
                 {telemetry.connectionStrength}%
               </span>
            </div>
            <div className="flex flex-col items-center">
               <MapPin size={18} className={getStatusColor(telemetry.gpsSignal, 30, 60)} />
               <span className={`text-xs font-bold ${getStatusColor(telemetry.gpsSignal, 30, 60)}`}>
                 {telemetry.gpsSignal}%
               </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6">
           <div className="text-right">
            <span className="text-[10px] text-zinc-500 uppercase">Mission Domain</span>
            <div className="text-cyan-400 font-bold text-sm">{currentMission}</div>
          </div>
          <div className={`px-4 py-1 border rounded text-xs font-bold animate-pulse ${
            currentMode === FlightMode.RETURN_TO_HOME || currentMode === FlightMode.EMERGENCY_LANDING 
            ? 'bg-red-900/40 border-red-500 text-red-400' 
            : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'
          }`}>
            {currentMode}
          </div>
          <button 
            onClick={resetSystem}
            className="p-2 hover:bg-zinc-800 rounded text-zinc-400 transition-colors"
            title="System Reset"
          >
            <RefreshCw size={18} />
          </button>
        </div>
      </div>

      {/* --- AI SUGGESTION BAR --- */}
      <div className={`mb-4 hud-border p-2 rounded flex items-center gap-3 backdrop-blur-md transition-all duration-500 ${
        isExecutingSuggestion ? 'bg-cyan-600/30 border-cyan-400' :
        riskAssessment.level === 'CRITICAL' ? 'bg-red-900/30 border-red-500/50' :
        riskAssessment.level === 'CAUTION' ? 'bg-yellow-900/20 border-yellow-500/50' :
        'bg-cyan-900/10 border-cyan-500/30'
      }`}>
        <div className={`p-1.5 rounded-full ${
          isExecutingSuggestion ? 'bg-white text-cyan-600 animate-spin' :
          riskAssessment.level === 'CRITICAL' ? 'bg-red-500 text-black' :
          riskAssessment.level === 'CAUTION' ? 'bg-yellow-500 text-black' :
          'bg-cyan-500 text-black'
        }`}>
          {isExecutingSuggestion ? <RefreshCw size={14} /> : riskAssessment.icon}
        </div>
        <div className="flex flex-col flex-1">
          <span className={`text-[9px] font-black tracking-widest uppercase ${
            isExecutingSuggestion ? 'text-white animate-pulse' :
            riskAssessment.level === 'CRITICAL' ? 'text-red-400' :
            riskAssessment.level === 'CAUTION' ? 'text-yellow-400' :
            'text-cyan-400'
          }`}>
            {isExecutingSuggestion ? 'AI EXECUTION IN PROGRESS' : `AI Risk Assessment: ${riskAssessment.level}`}
          </span>
          <span className="text-xs font-bold text-zinc-200 tracking-tight">
            {isExecutingSuggestion ? `EXECUTING MANEUVER: ${riskAssessment.executableAction}...` : riskAssessment.suggestion}
          </span>
        </div>

        {/* --- FOLLOW SUGGESTION BUTTON --- */}
        <button
          onClick={handleFollowSuggestion}
          disabled={isExecutingSuggestion || riskAssessment.executableAction === 'NONE' || riskAssessment.confidence < 0.4}
          className={`px-4 py-2 rounded flex items-center gap-2 font-black text-[10px] tracking-tighter uppercase transition-all border-b-4 ${
            riskAssessment.confidence >= 0.7 
              ? 'bg-green-600 hover:bg-green-500 border-green-800 text-white shadow-[0_0_15px_rgba(34,197,94,0.3)]' 
              : riskAssessment.confidence >= 0.4
                ? 'bg-yellow-600 hover:bg-yellow-500 border-yellow-800 text-white'
                : 'bg-red-900/60 border-red-950 text-red-500 opacity-50 cursor-not-allowed'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          {riskAssessment.confidence < 0.4 ? 'Action Blocked' : isExecutingSuggestion ? 'Executing...' : 'Follow Suggestion'}
          {riskAssessment.confidence >= 0.4 && !isExecutingSuggestion && (
            <span className="ml-1 opacity-50">{(riskAssessment.confidence * 100).toFixed(0)}%</span>
          )}
        </button>

        <div className="flex items-center gap-4 pr-2 border-l border-zinc-800 pl-4 ml-2">
           <div className="flex items-center gap-1">
             <div className={`w-1.5 h-1.5 rounded-full ${telemetry.battery > 20 ? 'bg-green-500' : 'bg-red-500 animate-ping'}`} />
             <span className="text-[8px] text-zinc-500 uppercase">PWR</span>
           </div>
           <div className="flex items-center gap-1">
             <div className={`w-1.5 h-1.5 rounded-full ${telemetry.gpsSignal > 40 ? 'bg-green-500' : 'bg-red-500 animate-ping'}`} />
             <span className="text-[8px] text-zinc-500 uppercase">POS</span>
           </div>
        </div>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">

        {/* --- LEFT: SENSOR DATA & GAUGES --- */}
        <div className="w-1/4 flex flex-col gap-4 overflow-y-auto">

          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Altitude (AGL)</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.altitude / 500) * 100)}%` }}></div>
            </div>
          </div>

          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg flex flex-col items-center border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-2">Ground Velocity</span>
            <div className="text-4xl font-black text-cyan-400 tabular-nums">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
            <div className="w-full h-1 bg-zinc-800 mt-2 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-500 transition-all duration-300" style={{ width: `${Math.min(100, (telemetry.speed / 120) * 100)}%` }}></div>
            </div>
          </div>

          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-yellow-500">
            <span className="text-[10px] text-zinc-500 uppercase mb-4 block">Navigation & Environment</span>
            <div className="grid grid-cols-2 gap-2 text-center">
               <div className="bg-zinc-800/50 p-2 rounded">
                  <span className="text-[9px] text-zinc-500 block">PITCH</span>
                  <span className={`text-sm font-bold ${Math.abs(telemetry.pitch) > 10 ? 'text-red-400' : 'text-cyan-400'}`}>{telemetry.pitch.toFixed(1)}°</span>
               </div>
               <div className="bg-zinc-800/50 p-2 rounded">
