interface PotentialTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
    pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);

  // --- Tracking State ---
  const [potentialTargets, setPotentialTargets] = useState<PotentialTarget[]>([]);
  const [lockedTargetId, setLockedTargetId] = useState<string | null>(null);
  const [trackingDecision, setTrackingDecision] = useState<TrackingDecision | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- Simulated Potential Targets ---
  useEffect(() => {
    const generateTargets = () => {
      const targets: PotentialTarget[] = [
        { id: 'OBJ-001', x: 30, y: 40, width: 10, height: 12, label: 'PERSON_A' },
        { id: 'OBJ-002', x: 60, y: 55, width: 12, height: 15, label: 'VEHICLE_B' },
        { id: 'OBJ-003', x: 20, y: 20, width: 8, height: 10, label: 'STRUCTURE_C' },
      ];
      setPotentialTargets(targets);
    };
    generateTargets();
  }, []);

  // --- Dynamic Target Movement ---
  useEffect(() => {
    const interval = setInterval(() => {
      setPotentialTargets(prev => prev.map(t => ({
        ...t,
        x: Math.max(5, Math.min(85, t.x + (Math.random() - 0.5) * 1.5)),
        y: Math.max(5, Math.min(85, t.y + (Math.random() - 0.5) * 1.5)),
      })));
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // --- AI Tracking Decision Core ---
  const updateTrackingDecision = useCallback(async () => {
    if (isProcessing) return;
    setIsProcessing(true);

    const context = lockedTargetId 
      ? `Maintaining lock on ${lockedTargetId}. Environmental crowding medium.` 
      : "Scanning sector for potential targets of interest.";

    const decision = await getTrackingDecision(telemetry, currentMode, currentMission, lockedTargetId, context);
    setTrackingDecision(decision);

    setMessages(prev => [...prev.slice(-20), {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `Target Status: ${decision.status} | Action: ${decision.suggested_action}`,
      trackingData: decision
    }]);

    setIsProcessing(false);
  }, [lockedTargetId, telemetry, currentMode, currentMission, isProcessing]);

  useEffect(() => {
    const interval = setInterval(updateTrackingDecision, 5000);
    return () => clearInterval(interval);
  }, [updateTrackingDecision]);

  // --- Target Selection ---
  const handleTargetSelect = (id: string) => {
    if (lockedTargetId === id) {
      setLockedTargetId(null);
      setTrackingDecision(null);
      if (currentMode === FlightMode.AUTO_FOLLOW) setCurrentMode(FlightMode.ASSISTED);
    } else {
      setLockedTargetId(id);
      updateTrackingDecision();
    }
  };

  // --- Follow Execution ---
  const handleFollowSuggestion = async () => {
    if (!trackingDecision || trackingDecision.lock_confidence < 0.5) return;

    setIsExecutingSuggestion(true);
    setCurrentMode(FlightMode.AUTO_FOLLOW);

    // Simulate execution status
    await new Promise(r => setTimeout(r, 1500));
    setIsExecutingSuggestion(false);
  };

  // --- Camera & HUD ---
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(s => { if (videoRef.current) { videoRef.current.srcObject = s; setCameraActive(true); } })
      .catch(() => setCameraActive(false));
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setTelemetry(prev => {
        // Simple drift logic if auto-following
        let headingDrift = (Math.random() - 0.5);
        if (currentMode === FlightMode.AUTO_FOLLOW && lockedTargetId) {
          const target = potentialTargets.find(t => t.id === lockedTargetId);
          if (target) {
            // Adjust heading to center target (target.x = 50 is center)
            const diff = (target.x + target.width / 2) - 50;
            headingDrift = diff * 0.1;
          }
        }

        return {
          ...prev,
          altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * 0.5),
          battery: Math.max(0, prev.battery - 0.01),
          heading: (prev.heading + headingDrift + 360) % 360,
        };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentMode, lockedTargetId, potentialTargets]);

  useEffect(() => {
    setTelemetryHistory(prev => [...prev.slice(-20), { time: Date.now(), alt: telemetry.altitude, bat: telemetry.battery }]);
  }, [telemetry]);

  // --- UI Helpers ---
  const getRiskColor = (risk: string) => {
    if (risk === 'High') return 'text-red-500';
    if (risk === 'Medium') return 'text-yellow-500';
    return 'text-green-500';
  };

  const getStatusIcon = (status: TrackingStatus) => {
    switch (status) {
      case TrackingStatus.LOCKED: return <Lock size={14} className="text-green-400" />;
      case TrackingStatus.LOST: return <EyeOff size={14} className="text-red-500" />;
      case TrackingStatus.OCCLUDED: return <Eye size={14} className="text-yellow-500" />;
      default: return <Search size={14} className="text-cyan-400" />;
    }
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden text-[#00ffcc] font-mono`}>

      {/* Top HUD */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 font-bold tracking-tighter uppercase">AI Decision Core</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className="text-cyan-400 animate-pulse" />
              <span className="font-bold tracking-widest">AEGIS-CORE v4.2</span>
            </div>
          </div>
          <div className="h-8 w-px bg-zinc-700" />
          <div className="flex items-center gap-4 text-xs font-bold">
            <div className="flex items-center gap-2"><Battery size={16} className={telemetry.battery < 20 ? 'text-red-500' : 'text-cyan-400'} /> {telemetry.battery.toFixed(0)}%</div>
            <div className="flex items-center gap-2"><MapPin size={16} className="text-cyan-400" /> GPS:{telemetry.gpsSignal}%</div>
            <div className="flex items-center gap-2"><Radio size={16} className="text-cyan-400" /> LINK:{telemetry.connectionStrength}%</div>
          </div>
        </div>
