            <span className="ml-2 text-zinc-500">Status:</span> 
            <span className={trackingDecision?.status === 'LOST' ? 'text-red-500' : 'text-cyan-400'}>{trackingDecision?.status || 'IDLE'}</span>
            {trackingDecision && (
              <>
                <span className="ml-2 text-zinc-500">Confidence:</span> 
                <span className="text-white">{(trackingDecision.lock_confidence * 100).toFixed(0)}%</span>
                <span className="ml-2 text-zinc-500">Risk:</span> 
                <span className={getRiskColor(trackingDecision.risk_level)}>{trackingDecision.risk_level}</span>
              </>
            )}
          </div>
          <div className="text-xs font-bold text-zinc-200 truncate">
            {isExecutingSuggestion ? 'AUTO-FOLLOWING TARGET VECTORS...' : trackingDecision?.suggested_action || 'System scanning for objects of interest...'}
          </div>
        </div>

        <button
          onClick={handleFollowSuggestion}
          disabled={!trackingDecision || trackingDecision.lock_confidence < 0.5 || isExecutingSuggestion}
          className={`px-4 py-1.5 rounded flex items-center gap-2 font-black text-[10px] uppercase border-b-4 transition-all ${
            trackingDecision && trackingDecision.lock_confidence >= 0.7 
              ? 'bg-green-600 hover:bg-green-500 border-green-800 text-white shadow-lg' 
              : trackingDecision && trackingDecision.lock_confidence >= 0.4
                ? 'bg-yellow-600 hover:bg-yellow-500 border-yellow-800 text-white'
                : 'bg-zinc-800 border-zinc-950 text-zinc-600 cursor-not-allowed opacity-50'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          {isExecutingSuggestion ? 'Active' : 'Follow Suggestion'}
        </button>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">
        {/* Left Gauges */}
        <div className="w-1/4 flex flex-col gap-4">
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500 text-center">
            <span className="text-[10px] text-zinc-500 uppercase">Altitude</span>
            <div className="text-4xl font-black">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
          </div>
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500 text-center">
            <span className="text-[10px] text-zinc-500 uppercase">Speed</span>
            <div className="text-4xl font-black">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
          </div>
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-2 overflow-hidden flex flex-col gap-2">
            <span className="text-[9px] text-zinc-500 uppercase">Telemetry Profiles</span>
            <div className="flex-1 h-20">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={telemetryHistory}><Area type="monotone" dataKey="alt" stroke="#00ffcc" fill="#00ffcc22" /></AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Video Feed */}
        <div className="flex-1 relative bg-black rounded-lg border border-zinc-800 overflow-hidden group">
          {cameraActive ? (
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover opacity-60 mix-blend-screen" />
          ) : (
            <div className="flex items-center justify-center h-full text-zinc-800 flex-col gap-2 uppercase font-black text-xs tracking-widest"><VideoOff size={48} /> No Camera Feed</div>
          )}

          {/* HUD Overlays */}
          <div className="absolute inset-0 pointer-events-none p-6">
