                <div className="w-32 h-32 border border-cyan-500/20 rounded-full animate-ping" />
                <Crosshair className="text-cyan-500/30" />
              </div>
            </div>
            <div className="absolute top-4 left-4 text-[10px] text-cyan-500/40">LAT: 34.05°N | LON: 118.24°W</div>
          </div>

          {/* Potential Target Selectors */}
          {potentialTargets.map(t => (
            <div
              key={t.id}
              onClick={(e) => { e.stopPropagation(); handleTargetSelect(t.id); }}
              className={`absolute cursor-pointer transition-all duration-300 pointer-events-auto flex items-center justify-center ${
                lockedTargetId === t.id ? 'z-50' : 'z-20 opacity-40 hover:opacity-100'
              }`}
              style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.width}%`, height: `${t.height}%` }}
            >
              <div className={`absolute inset-0 border-2 ${lockedTargetId === t.id ? 'border-red-500 shadow-[0_0_15px_rgba(239,68,68,0.5)]' : 'border-cyan-500'} transition-colors`}>
                <div className="absolute -top-1 -left-1 w-2 h-2 border-t-2 border-l-2 border-inherit" />
                <div className="absolute -top-1 -right-1 w-2 h-2 border-t-2 border-r-2 border-inherit" />
                <div className="absolute -bottom-1 -left-1 w-2 h-2 border-b-2 border-l-2 border-inherit" />
                <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b-2 border-r-2 border-inherit" />
              </div>
              <div className={`absolute -top-8 left-0 text-[8px] font-black px-1.5 py-0.5 whitespace-nowrap uppercase ${lockedTargetId === t.id ? 'bg-red-500 text-black' : 'bg-cyan-500 text-black'}`}>
                {lockedTargetId === t.id && <Lock size={8} className="inline mr-1 mb-0.5" />}
                {t.label} {lockedTargetId === t.id && `(LOCKED)`}
              </div>
            </div>
          ))}

          {/* Interaction Guide */}
          {!lockedTargetId && (
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/60 px-4 py-1.5 rounded-full border border-cyan-500/30 text-[9px] font-black uppercase text-cyan-400 tracking-tighter animate-bounce flex items-center gap-2">
              <TargetIcon size={12} /> Select object to lock track
            </div>
          )}
        </div>

        {/* Decision Log */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/60 rounded-lg flex flex-col overflow-hidden backdrop-blur-sm border-r-4 border-r-cyan-500/50">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/40 flex items-center justify-between">
              <span className="font-bold text-xs tracking-widest flex items-center gap-2"><Cpu size={14} className="text-cyan-400" /> Decision Stream</span>
              <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-400 animate-ping' : 'bg-cyan-400 animate-pulse'}`} />
            </div>
            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-3 font-mono text-[10px]">
              {messages.map((m) => (
                <div key={m.id} className="flex flex-col gap-1">
                  <span className="text-[8px] opacity-40 uppercase tracking-tighter">{m.timestamp} >> {m.type}</span>
                  <div className={`p-2 rounded border ${m.type === 'AI' ? 'bg-cyan-950/20 border-cyan-500/20' : 'bg-zinc-900/40 border-zinc-700/30'}`}>
                    {m.content}
                    {m.trackingData && (
                      <div className="mt-2 pt-2 border-t border-cyan-500/10 text-[9px] opacity-80 grid grid-cols-2 gap-1">
                        <div>ID: {m.trackingData.target_id}</div>
                        <div>CONF: {(m.trackingData.lock_confidence * 100).toFixed(0)}%</div>
                        <div className="col-span-2 text-yellow-500">REASON: {m.trackingData.reason}</div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>
          </div>
        </div>
      </div>

      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
        <span>Aegis UAV Supervisory System v4.2.0-STABLE</span>
        <div className="flex gap-4">
          <span>Storage: 91% Free</span>
          <span>Enc: AES-256-GCM</span>
          <span className="text-cyan-500">Autonomous Follow: {currentMode === FlightMode.AUTO_FOLLOW ? 'ACTIVE' : 'READY'}</span>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { 
  Battery, 
  MapPin, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  ArrowUp,
  Radio,
  AlertTriangle,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search,
  Info,
  ShieldCheck,
  PlayCircle,
  Crosshair,
  Lock,
  Unlock,
  Eye,
  EyeOff,
  Zap
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage, TrackingStatus, TrackingDecision } from './types';
import { getTrackingDecision } from './services/geminiService';

interface PotentialTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
    pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [userInput, setUserInput] = useState("");

  // --- Tracking State ---
  const [potentialTargets, setPotentialTargets] = useState<PotentialTarget[]>([]);
  const [lockedTargetId, setLockedTargetId] = useState<string | null>(null);
  const [trackingDecision, setTrackingDecision] = useState<TrackingDecision | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- Simulated Potential Targets ---
  useEffect(() => {
    const generateTargets = () => {
      const targets: PotentialTarget[] = [
        { id: 'OBJ-001', x: 30, y: 40, width: 10, height: 12, label: 'PERSON_A' },
        { id: 'OBJ-002', x: 60, y: 55, width: 12, height: 15, label: 'VEHICLE_B' },
        { id: 'OBJ-003', x: 20, y: 20, width: 8, height: 10, label: 'STRUCTURE_C' },
      ];
      setPotentialTargets(targets);
    };
    generateTargets();
  }, []);

  // --- Dynamic Target Movement ---
  useEffect(() => {
    const interval = setInterval(() => {
      setPotentialTargets(prev => prev.map(t => ({
        ...t,
        x: Math.max(5, Math.min(85, t.x + (Math.random() - 0.5) * 1.5)),
        y: Math.max(5, Math.min(85, t.y + (Math.random() - 0.5) * 1.5)),
      })));
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // --- AI Tracking Decision Core ---
  const updateTrackingDecision = useCallback(async (manualContext?: string) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const context = manualContext || (lockedTargetId 
      ? `Maintaining lock on ${lockedTargetId}. Environmental crowding medium.` 
      : "Scanning sector for potential targets of interest.");

    const decision = await getTrackingDecision(telemetry, currentMode, currentMission, lockedTargetId, context);
    setTrackingDecision(decision);

    setMessages(prev => [...prev.slice(-20), {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `Target Status: ${decision.status} | Action: ${decision.suggested_action}`,
      trackingData: decision
    }]);

    setIsProcessing(false);
  }, [lockedTargetId, telemetry, currentMode, currentMission, isProcessing]);

  useEffect(() => {
    const interval = setInterval(() => updateTrackingDecision(), 8000);
    return () => clearInterval(interval);
  }, [updateTrackingDecision]);

  // --- Manual Request Handler ---
  const handleAIRequest = useCallback(async (text?: string) => {
    const query = text || userInput;
    if (!query) return;

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'OPERATOR',
      content: query
    }]);

    await updateTrackingDecision(query);
    setUserInput("");
  }, [userInput, updateTrackingDecision]);

  // --- Emergency & Control Handlers ---
  const triggerEmergency = () => {
    setIsEmergency(true);
    setTelemetry(t => ({
      ...t,
      gpsSignal: 15,
      battery: 18,
      connectionStrength: 25
    }));
    handleAIRequest("SIMULATED CATASTROPHIC FAILURE DETECTED.");
  };

  const resetSystem = () => {
    setIsEmergency(false);
    setIsExecutingSuggestion(false);
    setLockedTargetId(null);
    setTrackingDecision(null);
    setTelemetry({
      altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
      pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
    });
    setCurrentMode(FlightMode.ASSISTED);
    setMessages([{
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "SYSTEM REBOOT COMPLETE. ALL DOMAINS NOMINAL."
    }]);
  };

  // --- Target Selection ---
  const handleTargetSelect = (id: string) => {
    if (lockedTargetId === id) {
      setLockedTargetId(null);
      setTrackingDecision(null);
      if (currentMode === FlightMode.AUTO_FOLLOW) setCurrentMode(FlightMode.ASSISTED);
    } else {
      setLockedTargetId(id);
      updateTrackingDecision();
    }
  };

  // --- Follow Execution ---
  const handleFollowSuggestion = async () => {
    if (!trackingDecision || trackingDecision.lock_confidence < 0.5) return;

    setIsExecutingSuggestion(true);
    setCurrentMode(FlightMode.AUTO_FOLLOW);

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "AI WILL EXECUTE RECOMMENDED SAFE MANEUVER: " + trackingDecision.suggested_action
    }]);

    await new Promise(r => setTimeout(r, 2000));
    setIsExecutingSuggestion(false);
  };

  // --- Camera & HUD ---
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(s => { if (videoRef.current) { videoRef.current.srcObject = s; setCameraActive(true); } })
      .catch(() => setCameraActive(false));
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setTelemetry(prev => {
        let headingDrift = (Math.random() - 0.5) * 0.2;
        if (currentMode === FlightMode.AUTO_FOLLOW && lockedTargetId) {
          const target = potentialTargets.find(t => t.id === lockedTargetId);
          if (target) {
            const diff = (target.x + target.width / 2) - 50;
            headingDrift = diff * 0.15;
          }
        }

        return {
          ...prev,
          altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * 0.4),
          battery: Math.max(0, prev.battery - (isEmergency ? 0.05 : 0.01)),
          heading: (prev.heading + headingDrift + 360) % 360,
        };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentMode, lockedTargetId, potentialTargets, isEmergency]);

  useEffect(() => {
    setTelemetryHistory(prev => [...prev.slice(-20), { time: Date.now(), alt: telemetry.altitude, bat: telemetry.battery }]);
  }, [telemetry]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- UI Helpers ---
  const getRiskColor = (risk: string) => {
    if (risk === 'High') return 'text-red-500';
    if (risk === 'Medium') return 'text-yellow-500';
    return 'text-green-500';
  };

  const getStatusIcon = (status: TrackingStatus) => {
    switch (status) {
      case TrackingStatus.LOCKED: return <Lock size={14} className="text-green-400" />;
      case TrackingStatus.LOST: return <EyeOff size={14} className="text-red-500" />;
      case TrackingStatus.OCCLUDED: return <Eye size={14} className="text-yellow-500" />;
      default: return <Search size={14} className="text-cyan-400" />;
    }
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden text-[#00ffcc] font-mono relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {/* Top HUD */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-sm">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[10px] text-zinc-500 font-bold tracking-tighter uppercase">AI Decision Core</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`text-cyan-400 ${isEmergency ? 'text-red-500' : 'animate-pulse'}`} />
              <span className="font-bold tracking-widest">AEGIS-CORE v4.2.1</span>
            </div>
          </div>
          <div className="h-8 w-px bg-zinc-700" />
          <div className="flex items-center gap-4 text-xs font-bold">
            <div className="flex items-center gap-2"><Battery size={16} className={telemetry.battery < 20 ? 'text-red-500 animate-pulse' : 'text-cyan-400'} /> {telemetry.battery.toFixed(0)}%</div>
            <div className="flex items-center gap-2"><MapPin size={16} className={telemetry.gpsSignal < 30 ? 'text-red-500' : 'text-cyan-400'} /> GPS:{telemetry.gpsSignal}%</div>
            <div className="flex items-center gap-2"><Radio size={16} className="text-cyan-400" /> LINK:{telemetry.connectionStrength}%</div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className={`px-4 py-1 border rounded text-[10px] font-black animate-pulse ${currentMode === FlightMode.AUTO_FOLLOW || currentMode === FlightMode.AUTONOMOUS ? 'bg-green-900/40 border-green-500 text-green-400' : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'}`}>
            {currentMode}
          </div>
          <button onClick={resetSystem} className="p-2 hover:bg-zinc-800 rounded transition-colors text-zinc-400"><RefreshCw size={18} /></button>
        </div>
      </div>

      {/* Suggestion Bar */}
      <div className={`mb-4 hud-border p-2 rounded flex items-center gap-3 backdrop-blur-md transition-all ${isExecutingSuggestion ? 'bg-green-600/30 border-green-400' : 'bg-zinc-900/40 border-zinc-700/50'}`}>
        <div className={`p-1.5 rounded-full ${isExecutingSuggestion ? 'bg-white text-green-600 animate-spin' : 'bg-cyan-500 text-black'}`}>
          {isExecutingSuggestion ? <RefreshCw size={14} /> : (trackingDecision ? getStatusIcon(trackingDecision.status as TrackingStatus) : <Search size={14} />)}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 text-[9px] font-black uppercase tracking-widest">
            <span className="text-zinc-500">Target ID:</span> 
            <span className="text-white">{trackingDecision?.target_id || (lockedTargetId ? lockedTargetId : 'NO_LOCK')}</span>
            <span className="ml-2 text-zinc-500">Status:</span> 
            <span className={trackingDecision?.status === 'LOST' ? 'text-red-500' : 'text-cyan-400'}>{trackingDecision?.status || 'IDLE'}</span>
            {trackingDecision && (
              <>
                <span className="ml-2 text-zinc-500">Confidence:</span> 
                <span className="text-white">{(trackingDecision.lock_confidence * 100).toFixed(0)}%</span>
                <span className="ml-2 text-zinc-500">Risk:</span> 
                <span className={getRiskColor(trackingDecision.risk_level)}>{trackingDecision.risk_level}</span>
              </>
            )}
          </div>
          <div className="text-xs font-bold text-zinc-200 truncate">
            {isExecutingSuggestion ? 'AI WILL EXECUTE RECOMMENDED SAFE MANEUVER...' : trackingDecision?.suggested_action || 'System scanning for objects of interest...'}
          </div>
        </div>

        <button
          onClick={handleFollowSuggestion}
          disabled={!trackingDecision || trackingDecision.lock_confidence < 0.5 || isExecutingSuggestion}
          className={`px-4 py-1.5 rounded flex items-center gap-2 font-black text-[10px] uppercase border-b-4 transition-all ${
            trackingDecision && trackingDecision.lock_confidence >= 0.7 
              ? 'bg-green-600 hover:bg-green-500 border-green-800 text-white' 
              : trackingDecision && trackingDecision.lock_confidence >= 0.4
                ? 'bg-yellow-600 hover:bg-yellow-500 border-yellow-800 text-white'
                : 'bg-zinc-800 border-zinc-950 text-zinc-600 cursor-not-allowed opacity-50'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          {isExecutingSuggestion ? 'Executing...' : (trackingDecision && trackingDecision.lock_confidence < 0.4 ? 'Action Blocked' : 'Follow Suggestion')}
        </button>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">
        {/* Left Gauges */}
        <div className="w-1/4 flex flex-col gap-4">
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500 text-center">
            <span className="text-[10px] text-zinc-500 uppercase">Altitude</span>
            <div className="text-4xl font-black">{telemetry.altitude.toFixed(1)}<span className="text-sm font-normal ml-1">m</span></div>
          </div>
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500 text-center">
            <span className="text-[10px] text-zinc-500 uppercase">Speed</span>
            <div className="text-4xl font-black">{telemetry.speed.toFixed(1)}<span className="text-sm font-normal ml-1">km/h</span></div>
          </div>
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-2 overflow-hidden flex flex-col gap-2">
            <span className="text-[9px] text-zinc-500 uppercase">Telemetry Profiles</span>
            <div className="flex-1 h-20">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={telemetryHistory}><Area type="monotone" dataKey="alt" stroke="#00ffcc" fill="#00ffcc22" /></AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Video Feed & Controls */}
        <div className="flex-1 flex flex-col gap-4">
          <div className="flex-1 relative bg-black rounded-lg border border-zinc-800 overflow-hidden group">
            {cameraActive ? (
              <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover mix-blend-screen transition-opacity ${isEmergency ? 'opacity-30' : 'opacity-60'}`} />
            ) : (
              <div className="flex items-center justify-center h-full text-zinc-800 flex-col gap-2 uppercase font-black text-xs tracking-widest"><VideoOff size={48} /> No Camera Feed</div>
            )}

            {/* HUD Overlays */}
            <div className="absolute inset-0 pointer-events-none p-6">
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border border-cyan-500/10 rounded-full flex items-center justify-center">
                  <div className="w-32 h-32 border border-cyan-500/20 rounded-full animate-ping" />
                  <Crosshair className="text-cyan-500/30" />
                </div>
              </div>
            </div>

            {/* Potential Target Selectors */}
            {potentialTargets.map(t => (
              <div
                key={t.id}
                onClick={(e) => { e.stopPropagation(); handleTargetSelect(t.id); }}
                className={`absolute cursor-pointer transition-all duration-300 pointer-events-auto flex items-center justify-center ${
                  lockedTargetId === t.id ? 'z-50' : 'z-20 opacity-40 hover:opacity-100'
                }`}
                style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.width}%`, height: `${t.height}%` }}
              >
                <div className={`absolute inset-0 border-2 ${lockedTargetId === t.id ? 'border-red-500 shadow-[0_0_15px_rgba(239,68,68,0.5)]' : 'border-cyan-500'}`}>
                  <div className="absolute -top-1 -left-1 w-2 h-2 border-t-2 border-l-2 border-inherit" />
                  <div className="absolute -top-1 -right-1 w-2 h-2 border-t-2 border-r-2 border-inherit" />
                  <div className="absolute -bottom-1 -left-1 w-2 h-2 border-b-2 border-l-2 border-inherit" />
                  <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b-2 border-r-2 border-inherit" />
                </div>
                <div className={`absolute -top-8 left-0 text-[8px] font-black px-1.5 py-0.5 whitespace-nowrap uppercase ${lockedTargetId === t.id ? 'bg-red-500 text-black' : 'bg-cyan-500 text-black'}`}>
                  {lockedTargetId === t.id && <Lock size={8} className="inline mr-1 mb-0.5" />}
                  {t.label}
                </div>
              </div>
            ))}
          </div>

          {/* Restored Flight Mode Control Panel */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3">
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all border ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 text-white border-cyan-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} hover:border-cyan-500/50`}
             >
                <Navigation size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Autonomous</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => updateTrackingDecision("Initiating deep sector scan.")}
                className="flex-1 py-2 rounded bg-zinc-800/50 text-cyan-400 border border-zinc-700 hover:border-cyan-500/50 flex flex-col items-center justify-center transition-colors"
             >
                <Search size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Target Scan</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.RETURN_TO_HOME)}
                className={`flex-1 py-2 rounded flex flex-col items-center justify-center transition-all border ${currentMode === FlightMode.RETURN_TO_HOME ? 'bg-yellow-600 text-white border-yellow-400' : 'bg-zinc-800/50 text-zinc-500 border-zinc-700'} hover:border-yellow-500/50`}
             >
                <ArrowUp size={18} className="rotate-180" />
                <span className="text-[9px] font-bold mt-1 uppercase">RTH</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={() => setCurrentMode(FlightMode.EMERGENCY_LANDING)}
                className="flex-1 py-2 rounded bg-red-900/40 text-red-500 border border-red-500/50 flex flex-col items-center justify-center hover:bg-red-900/60 transition-colors"
             >
                <ShieldAlert size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Emergency</span>
             </button>
             <button 
                disabled={isProcessing}
                onClick={triggerEmergency}
                className="flex-1 py-2 rounded bg-orange-900/40 text-orange-500 border border-orange-500/50 flex flex-col items-center justify-center hover:bg-orange-900/60 transition-colors"
             >
                <Zap size={18} />
                <span className="text-[9px] font-bold mt-1 uppercase">Sim Crisis</span>
             </button>
          </div>
        </div>

        {/* Decision Stream */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/60 rounded-lg flex flex-col overflow-hidden backdrop-blur-sm border-r-4 border-r-cyan-500/50">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/40 flex items-center justify-between">
              <span className="font-bold text-xs tracking-widest flex items-center gap-2"><Cpu size={14} className="text-cyan-400" /> Decision Stream</span>
              <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-400 animate-ping' : 'bg-cyan-400 animate-pulse'}`} />
            </div>
            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-3 font-mono text-[10px]">
              {messages.map((m) => (
                <div key={m.id} className="flex flex-col gap-1">
                  <span className="text-[8px] opacity-40 uppercase tracking-tighter">{m.timestamp} >> {m.type}</span>
                  <div className={`p-2 rounded border ${m.type === 'AI' ? 'bg-cyan-950/20 border-cyan-500/20' : m.type === 'OPERATOR' ? 'text-zinc-400' : 'bg-zinc-900/40 border-zinc-700/30'}`}>
                    {m.content}
                    {m.trackingData && (
                      <div className="mt-2 pt-2 border-t border-cyan-500/10 text-[9px] opacity-80 grid grid-cols-2 gap-1">
                        <div>ID: {m.trackingData.target_id}</div>
                        <div>CONF: {(m.trackingData.lock_confidence * 100).toFixed(0)}%</div>
                        <div className="col-span-2 text-yellow-500">REASON: {m.trackingData.reason}</div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>
            <div className="p-3 border-t border-zinc-800 bg-zinc-900/60">
              <div className="flex gap-2">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && !isProcessing && handleAIRequest()}
                  placeholder="Query decision core..."
                  className="flex-1 bg-black border border-zinc-700 text-cyan-400 p-2 rounded text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={isProcessing}
                  className="bg-cyan-900/30 border border-cyan-500/50 text-cyan-400 px-4 py-2 rounded text-[10px] font-bold hover:bg-cyan-900/50"
                >
                  EXEC
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
        <span>Aegis UAV Supervisory System v4.2.1-STABLE</span>
        <div className="flex gap-4">
          <span>Storage: 91% Free</span>
          <span>Enc: AES-256-GCM</span>
          <span className="text-cyan-500">Autonomous Follow: {currentMode === FlightMode.AUTO_FOLLOW ? 'ACTIVE' : 'READY'}</span>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { 
  Battery, 
  MapPin, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  ArrowUp,
  Radio,
  AlertTriangle,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search,
  Info,
  ShieldCheck,
  PlayCircle,
  Crosshair,
  Lock,
  Unlock,
  Eye,
  EyeOff,
  Zap,
  MessageSquare,
  Terminal,
  Send,
  MoreVertical
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage, TrackingStatus, TrackingDecision } from './types';
import { getTrackingDecision } from './services/geminiService';

interface PotentialTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
    pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [userInput, setUserInput] = useState("");

  // --- Tracking State ---
  const [potentialTargets, setPotentialTargets] = useState<PotentialTarget[]>([]);
  const [lockedTargetId, setLockedTargetId] = useState<string | null>(null);
  const [trackingDecision, setTrackingDecision] = useState<TrackingDecision | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- Simulated Potential Targets ---
  useEffect(() => {
    const generateTargets = () => {
      const targets: PotentialTarget[] = [
        { id: 'OBJ-001', x: 30, y: 40, width: 10, height: 12, label: 'PERSON_ALPHA' },
        { id: 'OBJ-002', x: 60, y: 55, width: 12, height: 15, label: 'VEHICLE_BETA' },
        { id: 'OBJ-003', x: 15, y: 25, width: 8, height: 10, label: 'CARGO_GAMMA' },
      ];
      setPotentialTargets(targets);
    };
    generateTargets();
  }, []);

  // --- Dynamic Target Movement ---
  useEffect(() => {
    const interval = setInterval(() => {
      setPotentialTargets(prev => prev.map(t => ({
        ...t,
        x: Math.max(5, Math.min(85, t.x + (Math.random() - 0.5) * 1.8)),
        y: Math.max(5, Math.min(85, t.y + (Math.random() - 0.5) * 1.8)),
      })));
    }, 400);
    return () => clearInterval(interval);
  }, []);

  // --- AI Tracking Decision Core ---
  const updateTrackingDecision = useCallback(async (manualContext?: string) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const context = manualContext || (lockedTargetId 
      ? `Analyzing locked target ${lockedTargetId}.` 
      : "Scanning environment for tactical objects.");

    const decision = await getTrackingDecision(telemetry, currentMode, currentMission, lockedTargetId, context);
    setTrackingDecision(decision);

    // Command Parsing from AI Content
    if (decision.suggested_action.toLowerCase().includes("home") || decision.suggested_action.toLowerCase().includes("rtl")) {
      // We don't auto-execute here, but we mark it as followable
    }

    setMessages(prev => [...prev.slice(-40), {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `Target [${decision.target_id}] analyzed. Status: ${decision.status}. Suggested: ${decision.suggested_action}. Reasoning: ${decision.reason}`,
      trackingData: decision
    }]);

    setIsProcessing(false);
  }, [lockedTargetId, telemetry, currentMode, currentMission, isProcessing]);

  // --- Manual Request Handler & Intent Parsing ---
  const handleAIRequest = useCallback(async (text?: string) => {
    const query = text || userInput;
    if (!query) return;

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'OPERATOR',
      content: query
    }]);

    // Local Intent Parsing for rapid control
    const lowQuery = query.toLowerCase();
    if (lowQuery.includes("home") || lowQuery.includes("rtl")) {
      setCurrentMode(FlightMode.RETURN_TO_HOME);
    } else if (lowQuery.includes("land")) {
      setCurrentMode(FlightMode.EMERGENCY_LANDING);
    } else if (lowQuery.includes("follow") && lockedTargetId) {
      handleFollowSuggestion();
    } else if (lowQuery.includes("scan")) {
      updateTrackingDecision("Conducting deep sector scan as requested.");
    }

    await updateTrackingDecision(query);
    setUserInput("");
  }, [userInput, updateTrackingDecision, lockedTargetId]);

  // --- Follow Execution ---
  const handleFollowSuggestion = async () => {
    if (!trackingDecision || trackingDecision.lock_confidence < 0.4) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: "EXECUTION BLOCKED: LOCK STABILITY INSUFFICIENT."
      }]);
      return;
    }

    setIsExecutingSuggestion(true);
    setCurrentMode(FlightMode.AUTO_FOLLOW);

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: "AUTONOMOUS FOLLOW ENGAGED. VECTORING TO TARGET " + trackingDecision.target_id
    }]);

    await new Promise(r => setTimeout(r, 1500));
    setIsExecutingSuggestion(false);
  };

  // --- Target Selection ---
  const handleTargetSelect = (id: string) => {
    if (lockedTargetId === id) {
      setLockedTargetId(null);
      setTrackingDecision(null);
      if (currentMode === FlightMode.AUTO_FOLLOW) setCurrentMode(FlightMode.ASSISTED);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `TARGET ${id} DISENGAGED. RETURNING TO WIDE-AREA SCAN.`
      }]);
    } else {
      setLockedTargetId(id);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        timestamp: new Date().toLocaleTimeString(),
        type: 'SYSTEM',
        content: `ACQUIRING TARGET ${id}. INITIALIZING TRACKING SUITE...`
      }]);
      updateTrackingDecision(`Initiating priority lock on object ${id}.`);
    }
  };

  // --- Hardware Hooks ---
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(s => { if (videoRef.current) { videoRef.current.srcObject = s; setCameraActive(true); } })
      .catch(() => setCameraActive(false));

    const interval = setInterval(() => {
      setTelemetry(prev => {
        let headingDrift = (Math.random() - 0.5) * 0.1;
        if (currentMode === FlightMode.AUTO_FOLLOW && lockedTargetId) {
          const target = potentialTargets.find(t => t.id === lockedTargetId);
          if (target) {
            const diff = (target.x + target.width / 2) - 50;
            headingDrift = diff * 0.2; // Aggressive follow logic
          }
        }
        return {
          ...prev,
          altitude: Math.max(0, prev.altitude + (Math.random() - 0.5) * 0.3),
          battery: Math.max(0, prev.battery - 0.01),
          heading: (prev.heading + headingDrift + 360) % 360,
        };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentMode, lockedTargetId, potentialTargets]);

  useEffect(() => {
    setTelemetryHistory(prev => [...prev.slice(-20), { time: Date.now(), alt: telemetry.altitude, bat: telemetry.battery }]);
  }, [telemetry]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --- UI Helpers ---
  const getRiskColor = (risk: string) => {
    if (risk === 'High') return 'text-red-500';
    if (risk === 'Medium') return 'text-yellow-500';
    return 'text-green-500';
  };

  const getStatusIcon = (status: TrackingStatus) => {
    switch (status) {
      case TrackingStatus.LOCKED: return <Lock size={14} className="text-green-400" />;
      case TrackingStatus.LOST: return <EyeOff size={14} className="text-red-500" />;
      case TrackingStatus.OCCLUDED: return <Eye size={14} className="text-yellow-500" />;
      default: return <Search size={14} className="text-cyan-400" />;
    }
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden text-[#00ffcc] font-mono relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {/* Top HUD */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-md">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest">Autonomous Core</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`text-cyan-400 ${isEmergency ? 'text-red-500' : 'animate-pulse'}`} />
              <span className="font-bold tracking-[0.2em] text-sm">AEGIS-OS v5.0</span>
            </div>
          </div>
          <div className="h-8 w-px bg-zinc-700" />
          <div className="flex items-center gap-4 text-xs font-bold">
            <div className="flex items-center gap-2"><Battery size={16} className={telemetry.battery < 20 ? 'text-red-500 animate-pulse' : 'text-cyan-400'} /> {telemetry.battery.toFixed(0)}%</div>
            <div className="flex items-center gap-2"><MapPin size={16} className="text-cyan-400" /> GPS_STABLE</div>
            <div className="flex items-center gap-2"><Radio size={16} className="text-cyan-400" /> SAT_LINK: 98%</div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className={`px-4 py-1 border rounded text-[10px] font-black tracking-widest ${currentMode === FlightMode.AUTO_FOLLOW ? 'bg-green-900/40 border-green-500 text-green-400 animate-pulse' : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'}`}>
            MODE: {currentMode}
          </div>
          <button onClick={() => { setLockedTargetId(null); setCurrentMode(FlightMode.ASSISTED); }} className="p-2 hover:bg-zinc-800 rounded transition-colors text-zinc-400"><RefreshCw size={18} /></button>
        </div>
      </div>

      {/* Suggestion Bar */}
      <div className={`mb-4 hud-border p-2 rounded flex items-center gap-3 backdrop-blur-md transition-all ${isExecutingSuggestion ? 'bg-green-600/30 border-green-400' : 'bg-zinc-900/40 border-zinc-700/50'}`}>
        <div className={`p-1.5 rounded-full ${isExecutingSuggestion ? 'bg-white text-green-600 animate-spin' : 'bg-cyan-500 text-black'}`}>
          {isExecutingSuggestion ? <RefreshCw size={14} /> : (trackingDecision ? getStatusIcon(trackingDecision.status as TrackingStatus) : <Search size={14} />)}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 text-[9px] font-black uppercase tracking-widest">
            <span className="text-zinc-500">Active Target:</span> 
            <span className="text-white">{trackingDecision?.target_id || (lockedTargetId ? lockedTargetId : 'IDLE')}</span>
            {trackingDecision && (
              <>
                <span className="ml-2 text-zinc-500">Lock:</span> 
                <span className="text-white">{(trackingDecision.lock_confidence * 100).toFixed(0)}%</span>
                <span className="ml-2 text-zinc-500">Risk:</span> 
                <span className={getRiskColor(trackingDecision.risk_level)}>{trackingDecision.risk_level}</span>
              </>
            )}
          </div>
          <div className="text-xs font-bold text-zinc-200 truncate">
            {isExecutingSuggestion ? 'AUTONOMOUS VECTORING IN PROGRESS...' : trackingDecision?.suggested_action || 'No critical suggestions. System scanning...'}
          </div>
        </div>

        <button
          onClick={handleFollowSuggestion}
          disabled={!trackingDecision || trackingDecision.lock_confidence < 0.4 || isExecutingSuggestion}
          className={`px-4 py-1.5 rounded flex items-center gap-2 font-black text-[10px] uppercase border-b-4 transition-all ${
            trackingDecision && trackingDecision.lock_confidence >= 0.7 
              ? 'bg-green-600 hover:bg-green-500 border-green-800 text-white' 
              : trackingDecision && trackingDecision.lock_confidence >= 0.4
                ? 'bg-yellow-600 hover:bg-yellow-500 border-yellow-800 text-white'
                : 'bg-zinc-800 border-zinc-950 text-zinc-600 cursor-not-allowed opacity-50'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          {isExecutingSuggestion ? 'Vectoring' : 'Follow Suggestion'}
        </button>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">
        {/* Left Gauges */}
        <div className="w-1/5 flex flex-col gap-4">
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase block mb-1">Altitude (m)</span>
            <div className="text-3xl font-black">{telemetry.altitude.toFixed(1)}</div>
          </div>
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase block mb-1">Velocity (km/h)</span>
            <div className="text-3xl font-black">{telemetry.speed.toFixed(1)}</div>
          </div>
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-3 flex flex-col gap-2">
            <span className="text-[9px] text-zinc-500 uppercase font-black">Environmental Metrics</span>
            <div className="flex-1 overflow-hidden opacity-50">
               <ResponsiveContainer width="100%" height="100%">
                 <AreaChart data={telemetryHistory}><Area type="monotone" dataKey="alt" stroke="#00ffcc" fill="#00ffcc22" strokeWidth={1} /></AreaChart>
               </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Video Feed & Controls */}
        <div className="flex-1 flex flex-col gap-4">
          <div className="flex-1 relative bg-black rounded-lg border border-zinc-800 overflow-hidden group">
            {cameraActive ? (
              <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity ${isEmergency ? 'opacity-30' : 'opacity-70'}`} />
            ) : (
              <div className="flex items-center justify-center h-full text-zinc-800 flex-col gap-2 uppercase font-black text-[10px] tracking-widest"><VideoOff size={48} /> Signal Lost</div>
            )}

            {/* Target Boxes with Lock Buttons */}
            {potentialTargets.map(t => (
              <div
                key={t.id}
                className={`absolute transition-all duration-300 pointer-events-none ${
                  lockedTargetId === t.id ? 'z-50' : 'z-20'
                }`}
                style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.width}%`, height: `${t.height}%` }}
              >
                <div className={`absolute inset-0 border-2 transition-colors duration-500 ${lockedTargetId === t.id ? 'border-red-500 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'border-cyan-500/40'}`}>
                  {/* Lock Toggle Button - Pointer Events ON */}
                  <button 
                    onClick={(e) => { e.stopPropagation(); handleTargetSelect(t.id); }}
                    className={`absolute -top-10 left-1/2 -translate-x-1/2 pointer-events-auto flex items-center gap-1.5 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase transition-all ${
                      lockedTargetId === t.id 
                      ? 'bg-red-600 border-red-400 text-white hover:bg-red-500' 
                      : 'bg-black/60 border-cyan-500/50 text-cyan-400 hover:bg-cyan-500 hover:text-black'
                    }`}
                  >
                    {lockedTargetId === t.id ? <Lock size={10} /> : <Crosshair size={10} />}
                    {lockedTargetId === t.id ? 'UNLOCK' : 'LOCK TARGET'}
                  </button>
                </div>
                <div className={`absolute -bottom-6 left-0 text-[8px] font-black px-1 py-0.5 uppercase ${lockedTargetId === t.id ? 'text-red-500' : 'text-cyan-500 opacity-60'}`}>
                  {t.label} {lockedTargetId === t.id && '(PRIORITY)'}
                </div>
              </div>
            ))}

            {/* HUD Center Crosshair */}
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-12 h-12 border border-cyan-500/20 rounded-full flex items-center justify-center">
                 <div className="w-1 h-1 bg-cyan-500/40 rounded-full" />
              </div>
            </div>
          </div>

          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3">
             <button onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)} className={`flex-1 py-2 rounded flex flex-col items-center border ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 text-white' : 'bg-zinc-800/40 text-zinc-500'} hover:border-cyan-400`}><Navigation size={18} /><span className="text-[8px] font-bold mt-1 uppercase">Auto</span></button>
             <button onClick={() => updateTrackingDecision("Forced wide-scan.")} className="flex-1 py-2 rounded bg-zinc-800/40 text-cyan-400 border border-zinc-800 hover:border-cyan-400 flex flex-col items-center"><Search size={18} /><span className="text-[8px] font-bold mt-1 uppercase">Scan</span></button>
             <button onClick={() => setCurrentMode(FlightMode.RETURN_TO_HOME)} className={`flex-1 py-2 rounded flex flex-col items-center border ${currentMode === FlightMode.RETURN_TO_HOME ? 'bg-yellow-600 text-white' : 'bg-zinc-800/40 text-zinc-500'} hover:border-yellow-400`}><ArrowUp size={18} className="rotate-180" /><span className="text-[8px] font-bold mt-1 uppercase">RTH</span></button>
             <button onClick={() => setCurrentMode(FlightMode.EMERGENCY_LANDING)} className="flex-1 py-2 rounded bg-red-900/30 text-red-500 border border-red-500/40 flex flex-col items-center"><ShieldAlert size={18} /><span className="text-[8px] font-bold mt-1 uppercase">Land</span></button>
             <button onClick={() => setIsEmergency(true)} className="flex-1 py-2 rounded bg-orange-900/30 text-orange-500 border border-orange-500/40 flex flex-col items-center"><Zap size={18} /><span className="text-[8px] font-bold mt-1 uppercase">Sim</span></button>
          </div>
        </div>

        {/* --- REAL-TIME CHAT & COMMAND PANEL --- */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/80 rounded-lg flex flex-col overflow-hidden backdrop-blur-md border-r-4 border-r-cyan-500/50 shadow-2xl">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/60 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <MessageSquare size={16} className="text-cyan-400" />
                <span className="font-black text-[10px] tracking-widest uppercase">Command Center</span>
              </div>
              <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-500 animate-ping' : 'bg-cyan-500'}`} />
                <MoreVertical size={14} className="text-zinc-600" />
              </div>
            </div>

            {/* Chat History */}
            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-4 font-mono text-[10px] scroll-smooth">
              {messages.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full opacity-20 gap-2">
                  <Terminal size={40} />
                  <span className="uppercase tracking-widest font-black">Secure Terminal Link Active</span>
                </div>
              )}
              {messages.map((m) => (
                <div key={m.id} className={`flex flex-col gap-1.5 ${m.type === 'OPERATOR' ? 'items-end' : 'items-start'}`}>
                  <div className="flex items-center gap-2 text-[8px] font-black uppercase tracking-tighter opacity-40">
                    {m.type === 'AI' && <Cpu size={10} className="text-cyan-400" />}
                    <span>{m.type === 'AI' ? 'Aegis Core' : m.type}</span>
                    <span>•</span>
                    <span>{m.timestamp}</span>
                  </div>

                  <div className={`max-w-[90%] p-3 rounded-xl border leading-relaxed shadow-sm ${
                    m.type === 'AI' 
                      ? 'bg-cyan-950/20 border-cyan-500/30 text-cyan-50 shadow-[0_0_15px_rgba(0,255,204,0.05)]' 
                      : m.type === 'SYSTEM' 
                        ? 'bg-yellow-900/10 border-yellow-500/20 text-yellow-400 italic' 
                        : 'bg-zinc-900/60 border-zinc-700 text-zinc-300'
                  }`}>
                    {m.content}

                    {/* Chat Action Button */}
                    {m.type === 'AI' && m.trackingData && m.trackingData.lock_confidence > 0.4 && (
                      <div className="mt-3 pt-3 border-t border-cyan-500/20 flex flex-col gap-2">
                        <div className="flex justify-between items-center text-[8px] font-black text-cyan-500/60 uppercase">
                          <span>Vector Suggestion</span>
                          <span>Confidence: {(m.trackingData.lock_confidence * 100).toFixed(0)}%</span>
                        </div>
                        <button 
                          onClick={handleFollowSuggestion}
                          className="w-full bg-cyan-600/20 border border-cyan-500/50 hover:bg-cyan-600/40 text-cyan-400 py-1.5 rounded flex items-center justify-center gap-2 text-[9px] font-black transition-all group"
                        >
                          <PlayCircle size={10} className="group-hover:scale-110 transition-transform" />
                          EXECUTE: {m.trackingData.suggested_action}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-3 text-cyan-400 bg-cyan-950/20 p-3 rounded-lg border border-cyan-500/20 animate-pulse">
                  <Activity size={14} className="animate-spin" />
                  <span className="text-[9px] font-black tracking-widest uppercase">AI Core Reasoning...</span>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-3 border-t border-zinc-800 bg-zinc-900/40">
              <div className="relative group">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAIRequest()}
                  placeholder="Enter flight command or tactical query..."
                  className="w-full bg-black/80 border border-zinc-700 text-cyan-400 pl-4 pr-12 py-3 rounded-xl text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700 transition-all font-mono"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={!userInput || isProcessing}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg text-cyan-500 hover:text-cyan-300 disabled:opacity-20 transition-all"
                >
                  <Send size={18} />
                </button>
              </div>
              <div className="mt-2 flex justify-between px-2 text-[7px] font-black text-zinc-600 uppercase tracking-widest">
                <span>Terminal: Secured</span>
                <span>Latency: 12ms</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Global Status Footer */}
      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
        <div className="flex gap-4">
          <span>UAV_ID: AEGIS-7</span>
          <span>REGS: NX-2025-UAV</span>
          <span>UPTIME: {Math.floor(performance.now() / 1000)}S</span>
        </div>
        <div className="flex gap-4">
          <span className="text-cyan-500">AUTONOMOUS_FOLLOW: {currentMode === FlightMode.AUTO_FOLLOW ? 'ACTIVE' : 'READY'}</span>
          <span>SEC_MODE: AES-GCM-256</span>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Battery, 
  MapPin, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  ArrowUp,
  Radio,
  AlertTriangle,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search,
  Info,
  PlayCircle,
  Crosshair,
  Lock,
  Unlock,
  Eye,
  EyeOff,
  Zap,
  MessageSquare,
  Terminal,
  Send,
  MoreVertical,
  ShieldCheck,
  ZapOff
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage, TrackingStatus, TrackingDecision } from './types';
import { getTrackingDecision } from './services/geminiService';

interface PotentialTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
    pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [userInput, setUserInput] = useState("");

  // --- Tracking State ---
  const [potentialTargets, setPotentialTargets] = useState<PotentialTarget[]>([]);
  const [lockedTargetId, setLockedTargetId] = useState<string | null>(null);
  const [trackingDecision, setTrackingDecision] = useState<TrackingDecision | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- Initial Setup & Simulation ---
  useEffect(() => {
    setPotentialTargets([
      { id: 'TGT-ALPHA', x: 25, y: 35, width: 12, height: 14, label: 'SUSPECT_PERSON' },
      { id: 'TGT-BETA', x: 65, y: 50, width: 15, height: 18, label: 'VEHICLE_UNIDENTIFIED' },
      { id: 'TGT-GAMMA', x: 10, y: 20, width: 8, height: 10, label: 'STATIC_OBJ' },
    ]);

    setMessages([{
      id: 'init',
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: 'AEGIS COMMAND LINK SECURED. 256-BIT ENCRYPTION ACTIVE. ONBOARD AI STANDING BY.'
    }]);

    navigator.mediaDevices.getUserMedia({ video: true })
      .then(s => { if (videoRef.current) { videoRef.current.srcObject = s; setCameraActive(true); } })
      .catch(() => setCameraActive(false));
  }, []);

  // --- Target Movement Simulation ---
  useEffect(() => {
    const interval = setInterval(() => {
      setPotentialTargets(prev => prev.map(t => ({
        ...t,
        x: Math.max(5, Math.min(85, t.x + (Math.random() - 0.5) * 1.5)),
        y: Math.max(5, Math.min(85, t.y + (Math.random() - 0.5) * 1.5)),
      })));
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // --- AI Logic Integration ---
  const updateTrackingDecision = useCallback(async (manualContext?: string) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const context = manualContext || (lockedTargetId 
      ? `Maintaining active lock on ${lockedTargetId}.` 
      : "Performing standard area surveillance.");

    const decision = await getTrackingDecision(telemetry, currentMode, currentMission, lockedTargetId, context);
    setTrackingDecision(decision);

    setMessages(prev => [...prev.slice(-40), {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `Target ${decision.target_id} status: ${decision.status}. Suggested: ${decision.suggested_action}. Reason: ${decision.reason}`,
      trackingData: decision
    }]);

    setIsProcessing(false);
  }, [lockedTargetId, telemetry, currentMode, currentMission, isProcessing]);

  // --- Follow Action Handler ---
  const handleFollowSuggestion = async () => {
    if (!trackingDecision || trackingDecision.lock_confidence < 0.4) return;
    setIsExecutingSuggestion(true);
    setCurrentMode(FlightMode.AUTO_FOLLOW);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: `ENGAGING AUTONOMOUS FOLLOW: VECTORING TO ${trackingDecision.target_id}...`
    }]);
    await new Promise(r => setTimeout(r, 2000));
    setIsExecutingSuggestion(false);
  };

  // --- Chat & Command Intents ---
  const handleAIRequest = useCallback(async (text?: string) => {
    const query = text || userInput;
    if (!query) return;

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'OPERATOR',
      content: query
    }]);

    const lowQuery = query.toLowerCase();
    if (lowQuery.includes("home") || lowQuery.includes("rtl")) setCurrentMode(FlightMode.RETURN_TO_HOME);
    else if (lowQuery.includes("land")) setCurrentMode(FlightMode.EMERGENCY_LANDING);
    else if (lowQuery.includes("follow") && lockedTargetId) handleFollowSuggestion();
    else if (lowQuery.includes("autonomous")) setCurrentMode(FlightMode.AUTONOMOUS);
    else if (lowQuery.includes("scan")) updateTrackingDecision("Initiating deep sector scan.");

    await updateTrackingDecision(query);
    setUserInput("");
  }, [userInput, updateTrackingDecision, lockedTargetId, currentMode]);

  // --- Telemetry & Control Loops ---
  useEffect(() => {
    const interval = setInterval(() => {
      setTelemetry(prev => {
        let headingDrift = (Math.random() - 0.5) * 0.1;
        if (currentMode === FlightMode.AUTO_FOLLOW && lockedTargetId) {
          const target = potentialTargets.find(t => t.id === lockedTargetId);
          if (target) {
            const diff = (target.x + target.width / 2) - 50;
            headingDrift = diff * 0.2;
          }
        }
        return {
          ...prev,
          altitude: Math.max(10, prev.altitude + (Math.random() - 0.5) * 0.4),
          battery: Math.max(0, prev.battery - 0.01),
          heading: (prev.heading + headingDrift + 360) % 360,
        };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentMode, lockedTargetId, potentialTargets]);

  useEffect(() => {
    setTelemetryHistory(prev => [...prev.slice(-20), { time: Date.now(), alt: telemetry.altitude, bat: telemetry.battery }]);
  }, [telemetry]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleTargetToggle = (id: string) => {
    if (lockedTargetId === id) {
      setLockedTargetId(null);
      setTrackingDecision(null);
      setCurrentMode(FlightMode.ASSISTED);
    } else {
      setLockedTargetId(id);
      updateTrackingDecision(`Manual lock override on target ${id}.`);
    }
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden text-[#00ffcc] font-mono relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {/* HUD Header */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-md z-50">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest">Decision Hub</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`text-cyan-400 ${isEmergency ? 'text-red-500' : 'animate-pulse'}`} />
              <span className="font-bold tracking-widest text-sm">AEGIS-CORE v5.1</span>
            </div>
          </div>
          <div className="h-8 w-px bg-zinc-700" />
          <div className="flex gap-4 text-xs font-bold">
            <div className="flex items-center gap-2"><Battery size={16} className={telemetry.battery < 20 ? 'text-red-500' : 'text-cyan-400'} /> {telemetry.battery.toFixed(0)}%</div>
            <div className="flex items-center gap-2"><MapPin size={16} className="text-cyan-400" /> GPS_STABLE</div>
            <div className="flex items-center gap-2"><Radio size={16} className="text-cyan-400" /> LINK: 98%</div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className={`px-4 py-1 border rounded text-[10px] font-black tracking-widest ${currentMode === FlightMode.AUTO_FOLLOW || currentMode === FlightMode.AUTONOMOUS ? 'bg-green-900/40 border-green-500 text-green-400 animate-pulse' : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'}`}>
            FLIGHT_MODE: {currentMode}
          </div>
          <button onClick={() => { setLockedTargetId(null); setCurrentMode(FlightMode.ASSISTED); setIsEmergency(false); }} className="p-2 hover:bg-zinc-800 rounded text-zinc-400"><RefreshCw size={18} /></button>
        </div>
      </div>

      {/* Suggestion Bar */}
      <div className={`mb-4 hud-border p-2 rounded flex items-center gap-3 backdrop-blur-md transition-all z-50 ${isExecutingSuggestion ? 'bg-green-600/30 border-green-400' : 'bg-zinc-900/40 border-zinc-700/50'}`}>
        <div className={`p-1.5 rounded-full ${isExecutingSuggestion ? 'bg-white text-green-600 animate-spin' : 'bg-cyan-500 text-black'}`}>
          {isExecutingSuggestion ? <RefreshCw size={14} /> : (lockedTargetId ? <Lock size={14} /> : <Search size={14} />)}
        </div>
        <div className="flex-1">
          <div className="text-[9px] font-black uppercase tracking-widest flex gap-2">
            <span className="text-zinc-500">Lock Target:</span>
            <span className="text-white">{lockedTargetId || 'IDLE'}</span>
            {trackingDecision && (
              <>
                <span className="text-zinc-500 ml-2">Conf:</span>
                <span className="text-cyan-400">{(trackingDecision.lock_confidence * 100).toFixed(0)}%</span>
              </>
            )}
          </div>
          <div className="text-xs font-bold text-zinc-200 truncate">
            {isExecutingSuggestion ? 'AUTONOMOUS VECTORING ACTIVE...' : trackingDecision?.suggested_action || 'Scanning tactical environment...'}
          </div>
        </div>
        <button
          onClick={handleFollowSuggestion}
          disabled={!trackingDecision || trackingDecision.lock_confidence < 0.4 || isExecutingSuggestion}
          className={`px-6 py-2 rounded flex items-center gap-2 font-black text-[10px] uppercase border-b-4 transition-all ${
            trackingDecision && trackingDecision.lock_confidence >= 0.7 
              ? 'bg-green-600 border-green-800 text-white' 
              : trackingDecision && trackingDecision.lock_confidence >= 0.4
                ? 'bg-yellow-600 border-yellow-800 text-white'
                : 'bg-zinc-800 border-zinc-950 text-zinc-600 cursor-not-allowed opacity-50'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          Follow Suggestion
        </button>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">
        {/* Left Stats */}
        <div className="w-1/5 flex flex-col gap-4">
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase font-black block mb-1">ALT (m)</span>
            <div className="text-3xl font-black">{telemetry.altitude.toFixed(1)}</div>
          </div>
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase font-black block mb-1">SPD (km/h)</span>
            <div className="text-3xl font-black">{telemetry.speed.toFixed(1)}</div>
          </div>
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-3 flex flex-col gap-2">
            <span className="text-[9px] text-zinc-500 font-black uppercase">Tactical Feed Trend</span>
            <div className="flex-1 overflow-hidden opacity-30">
               <ResponsiveContainer width="100%" height="100%">
                 <AreaChart data={telemetryHistory}><Area type="monotone" dataKey="alt" stroke="#00ffcc" fill="#00ffcc" /></AreaChart>
               </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Video Feed & Control Panel */}
        <div className="flex-1 flex flex-col gap-4">
          <div className="flex-1 relative bg-black rounded-lg border border-zinc-800 overflow-hidden shadow-2xl">
            {cameraActive ? (
              <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity ${isEmergency ? 'opacity-30' : 'opacity-60'}`} />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-zinc-800 text-[10px] font-black uppercase"><VideoOff size={48} className="mb-2" /> Feed Offline</div>
            )}

            {/* In-HUD Target Controls */}
            {potentialTargets.map(t => (
              <div 
                key={t.id} 
                className="absolute transition-all duration-300 pointer-events-none"
                style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.width}%`, height: `${t.height}%` }}
              >
                <div className={`absolute inset-0 border-2 ${lockedTargetId === t.id ? 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'border-cyan-500/40'}`}>
                   <button 
                     onClick={(e) => { e.stopPropagation(); handleTargetToggle(t.id); }}
                     className={`absolute -top-12 left-1/2 -translate-x-1/2 pointer-events-auto px-4 py-1.5 rounded-full border text-[9px] font-black uppercase transition-all flex items-center gap-1.5 ${
                        lockedTargetId === t.id 
                        ? 'bg-red-600 border-red-400 text-white hover:bg-red-500' 
                        : 'bg-black/80 border-cyan-500/50 text-cyan-400 hover:bg-cyan-500 hover:text-black'
                     }`}
                   >
                     {lockedTargetId === t.id ? <Unlock size={10} /> : <Crosshair size={10} />}
                     {lockedTargetId === t.id ? 'DISENGAGE' : 'LOCK TRACK'}
                   </button>
                </div>
                <div className={`absolute -bottom-6 left-0 text-[8px] font-black uppercase ${lockedTargetId === t.id ? 'text-red-500' : 'text-cyan-500 opacity-60'}`}>
                  {t.label} {lockedTargetId === t.id && '(LOCKED)'}
                </div>
              </div>
            ))}
          </div>

          {/* Restored Main Control Panel */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3 shadow-xl">
             <button 
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-3 rounded-lg border flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 border-cyan-400 text-white' : 'bg-zinc-800/40 border-zinc-700 text-zinc-500'} hover:border-cyan-500`}
             >
                <Navigation size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Autonomous Flight</span>
             </button>
             <button onClick={() => updateTrackingDecision("Manual scan sweep triggered.")} className="flex-1 py-3 rounded-lg bg-zinc-800/40 border border-zinc-700 text-cyan-400 hover:border-cyan-500 flex flex-col items-center justify-center">
                <Search size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Tactical Scan</span>
             </button>
             <button onClick={() => setCurrentMode(FlightMode.RETURN_TO_HOME)} className="flex-1 py-3 rounded-lg bg-zinc-800/40 border border-zinc-700 text-yellow-500 hover:border-yellow-500 flex flex-col items-center justify-center">
                <ArrowUp size={20} className="rotate-180" />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">RTH Mode</span>
             </button>
             <button onClick={() => setCurrentMode(FlightMode.EMERGENCY_LANDING)} className="flex-1 py-3 rounded-lg bg-red-900/20 border border-red-500/40 text-red-500 hover:bg-red-900/40 flex flex-col items-center justify-center">
                <ShieldAlert size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Force Land</span>
             </button>
          </div>
        </div>

        {/* Command Center (Chat Panel) */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/80 rounded-lg flex flex-col overflow-hidden backdrop-blur-md border-r-4 border-r-cyan-500/50 shadow-2xl">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/60 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Terminal size={16} className="text-cyan-400" />
                <span className="font-black text-[10px] tracking-widest uppercase">Tactical Terminal</span>
              </div>
              <div className="flex items-center gap-3">
                <div className="text-[8px] font-black text-zinc-600 uppercase tracking-tighter">Secure Link</div>
                <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-500 animate-ping' : 'bg-cyan-500 animate-pulse'}`} />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-4 font-mono text-[10px] scroll-smooth">
              {messages.map((m) => (
                <div key={m.id} className={`flex flex-col gap-1 ${m.type === 'OPERATOR' ? 'items-end' : 'items-start'}`}>
                  <div className="flex items-center gap-2 text-[8px] font-black uppercase tracking-tighter opacity-40">
                    <span>{m.type === 'AI' ? 'Aegis_Core' : m.type}</span>
                    <span>•</span>
                    <span>{m.timestamp}</span>
                  </div>
                  <div className={`max-w-[85%] p-3 rounded-xl border leading-relaxed ${
                    m.type === 'AI' 
                      ? 'bg-cyan-950/20 border-cyan-500/30 text-cyan-50 shadow-[0_0_15px_rgba(0,255,204,0.05)]' 
                      : m.type === 'SYSTEM' ? 'bg-zinc-900/60 border-yellow-500/20 text-yellow-500 italic' 
                      : 'bg-zinc-900/80 border-zinc-700 text-zinc-400'
                  }`}>
                    {m.content}

                    {/* Inline Command Button */}
                    {m.type === 'AI' && m.trackingData && m.trackingData.lock_confidence > 0.4 && (
                      <div className="mt-3 pt-3 border-t border-cyan-500/20">
                        <button 
                          onClick={handleFollowSuggestion}
                          className="w-full bg-cyan-600/20 border border-cyan-500/50 hover:bg-cyan-600/40 text-cyan-400 py-1.5 rounded-lg flex items-center justify-center gap-2 text-[9px] font-black uppercase transition-all"
                        >
                          <PlayCircle size={10} />
                          Execute: {m.trackingData.suggested_action.split(' ').slice(0, 3).join(' ')}...
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-2 text-cyan-400 bg-cyan-900/10 p-2 rounded border border-cyan-900 animate-pulse">
                  <Activity size={12} className="animate-spin" />
                  <span className="text-[9px] font-black uppercase">Analyzing tactical intent...</span>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            <div className="p-3 border-t border-zinc-800 bg-zinc-900/40">
              <div className="relative">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAIRequest()}
                  placeholder="Query system or issue command..."
                  className="w-full bg-black border border-zinc-700 text-cyan-400 pl-4 pr-12 py-3 rounded-xl text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700 font-mono"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={!userInput || isProcessing}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg text-cyan-500 hover:text-cyan-300 disabled:opacity-20 transition-all"
                >
                  <Send size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Status */}
      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
        <div className="flex gap-4">
          <span>UAV_ALPHA_SEVEN</span>
          <span>UPTIME: {Math.floor(performance.now() / 1000)}S</span>
          <span>SEC: 256_BIT_AES</span>
        </div>
        <div className="flex gap-4">
          <span className="text-cyan-500">AUTONOMOUS_FOLLOW: {currentMode === FlightMode.AUTO_FOLLOW ? 'ACTIVE' : 'READY'}</span>
          <span>SIGNAL_DBM: -42</span>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Battery, 
  MapPin, 
  Navigation, 
  Activity, 
  Cpu, 
  ShieldAlert, 
  ArrowUp,
  Radio,
  AlertTriangle,
  RefreshCw,
  VideoOff,
  Target as TargetIcon,
  Search,
  Info,
  PlayCircle,
  Crosshair,
  Lock,
  Unlock,
  Eye,
  EyeOff,
  Zap,
  MessageSquare,
  Terminal,
  Send,
  MoreVertical,
  ShieldCheck,
  ZapOff
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { FlightMode, MissionType, Telemetry, DecisionMessage, TrackingStatus, TrackingDecision } from './types';
import { getTrackingDecision } from './services/geminiService';

interface PotentialTarget {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
}

const App: React.FC = () => {
  // --- Drone State ---
  const [telemetry, setTelemetry] = useState<Telemetry>({
    altitude: 120, speed: 45, battery: 88, gpsSignal: 95, windSpeed: 12,
    pitch: 2, roll: -1, yaw: 185, heading: 185, connectionStrength: 98, isWaterproofMode: false
  });

  const [currentMode, setCurrentMode] = useState<FlightMode>(FlightMode.ASSISTED);
  const [currentMission, setCurrentMission] = useState<MissionType>(MissionType.SURVEILLANCE);
  const [messages, setMessages] = useState<DecisionMessage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isExecutingSuggestion, setIsExecutingSuggestion] = useState(false);
  const [telemetryHistory, setTelemetryHistory] = useState<any[]>([]);
  const [isEmergency, setIsEmergency] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [userInput, setUserInput] = useState("");

  // --- Tracking State ---
  const [potentialTargets, setPotentialTargets] = useState<PotentialTarget[]>([]);
  const [lockedTargetId, setLockedTargetId] = useState<string | null>(null);
  const [trackingDecision, setTrackingDecision] = useState<TrackingDecision | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // --- Initial Setup & Simulation ---
  useEffect(() => {
    setPotentialTargets([
      { id: 'TGT-ALPHA', x: 25, y: 35, width: 12, height: 14, label: 'SUSPECT_PERSON' },
      { id: 'TGT-BETA', x: 65, y: 50, width: 15, height: 18, label: 'VEHICLE_UNIDENTIFIED' },
      { id: 'TGT-GAMMA', x: 10, y: 20, width: 8, height: 10, label: 'STATIC_OBJ' },
    ]);

    setMessages([{
      id: 'init',
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: 'AEGIS COMMAND LINK SECURED. 256-BIT ENCRYPTION ACTIVE. ONBOARD AI STANDING BY.'
    }]);

    navigator.mediaDevices.getUserMedia({ video: true })
      .then(s => { if (videoRef.current) { videoRef.current.srcObject = s; setCameraActive(true); } })
      .catch(() => setCameraActive(false));
  }, []);

  // --- Target Movement Simulation ---
  useEffect(() => {
    const interval = setInterval(() => {
      setPotentialTargets(prev => prev.map(t => ({
        ...t,
        x: Math.max(5, Math.min(85, t.x + (Math.random() - 0.5) * 1.5)),
        y: Math.max(5, Math.min(85, t.y + (Math.random() - 0.5) * 1.5)),
      })));
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // --- AI Logic Integration ---
  const updateTrackingDecision = useCallback(async (manualContext?: string) => {
    if (isProcessing) return;
    setIsProcessing(true);

    const context = manualContext || (lockedTargetId 
      ? `Maintaining active lock on ${lockedTargetId}.` 
      : "Performing standard area surveillance.");

    const decision = await getTrackingDecision(telemetry, currentMode, currentMission, lockedTargetId, context);
    setTrackingDecision(decision);

    setMessages(prev => [...prev.slice(-40), {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'AI',
      content: `Target ${decision.target_id} status: ${decision.status}. Suggested: ${decision.suggested_action}. Reason: ${decision.reason}`,
      trackingData: decision
    }]);

    setIsProcessing(false);
  }, [lockedTargetId, telemetry, currentMode, currentMission, isProcessing]);

  // --- Follow Action Handler ---
  const handleFollowSuggestion = async () => {
    if (!trackingDecision || trackingDecision.lock_confidence < 0.4) return;
    setIsExecutingSuggestion(true);
    setCurrentMode(FlightMode.AUTO_FOLLOW);
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'SYSTEM',
      content: `ENGAGING AUTONOMOUS FOLLOW: VECTORING TO ${trackingDecision.target_id}...`
    }]);
    await new Promise(r => setTimeout(r, 2000));
    setIsExecutingSuggestion(false);
  };

  // --- Chat & Command Intents ---
  const handleAIRequest = useCallback(async (text?: string) => {
    const query = text || userInput;
    if (!query) return;

    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleTimeString(),
      type: 'OPERATOR',
      content: query
    }]);

    const lowQuery = query.toLowerCase();
    if (lowQuery.includes("home") || lowQuery.includes("rtl")) setCurrentMode(FlightMode.RETURN_TO_HOME);
    else if (lowQuery.includes("land")) setCurrentMode(FlightMode.EMERGENCY_LANDING);
    else if (lowQuery.includes("follow") && lockedTargetId) handleFollowSuggestion();
    else if (lowQuery.includes("autonomous")) setCurrentMode(FlightMode.AUTONOMOUS);
    else if (lowQuery.includes("scan")) updateTrackingDecision("Initiating deep sector scan.");

    await updateTrackingDecision(query);
    setUserInput("");
  }, [userInput, updateTrackingDecision, lockedTargetId, currentMode]);

  // --- Telemetry & Control Loops ---
  useEffect(() => {
    const interval = setInterval(() => {
      setTelemetry(prev => {
        let headingDrift = (Math.random() - 0.5) * 0.1;
        if (currentMode === FlightMode.AUTO_FOLLOW && lockedTargetId) {
          const target = potentialTargets.find(t => t.id === lockedTargetId);
          if (target) {
            const diff = (target.x + target.width / 2) - 50;
            headingDrift = diff * 0.2;
          }
        }
        return {
          ...prev,
          altitude: Math.max(10, prev.altitude + (Math.random() - 0.5) * 0.4),
          battery: Math.max(0, prev.battery - 0.01),
          heading: (prev.heading + headingDrift + 360) % 360,
        };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentMode, lockedTargetId, potentialTargets]);

  useEffect(() => {
    setTelemetryHistory(prev => [...prev.slice(-20), { time: Date.now(), alt: telemetry.altitude, bat: telemetry.battery }]);
  }, [telemetry]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleTargetToggle = (id: string) => {
    if (lockedTargetId === id) {
      setLockedTargetId(null);
      setTrackingDecision(null);
      setCurrentMode(FlightMode.ASSISTED);
    } else {
      setLockedTargetId(id);
      updateTrackingDecision(`Manual lock override on target ${id}.`);
    }
  };

  return (
    <div className={`flex flex-col h-screen p-4 bg-black select-none overflow-hidden text-[#00ffcc] font-mono relative ${isEmergency ? 'animate-[pulse_4s_infinite]' : ''}`}>

      {/* HUD Header */}
      <div className="flex justify-between items-center mb-4 hud-border p-3 bg-zinc-900/50 rounded-lg backdrop-blur-md z-50">
        <div className="flex items-center gap-6">
          <div className="flex flex-col">
            <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest">Decision Hub</span>
            <div className="flex items-center gap-2">
              <Cpu size={16} className={`text-cyan-400 ${isEmergency ? 'text-red-500' : 'animate-pulse'}`} />
              <span className="font-bold tracking-widest text-sm">AEGIS-CORE v5.1</span>
            </div>
          </div>
          <div className="h-8 w-px bg-zinc-700" />
          <div className="flex gap-4 text-xs font-bold">
            <div className="flex items-center gap-2"><Battery size={16} className={telemetry.battery < 20 ? 'text-red-500' : 'text-cyan-400'} /> {telemetry.battery.toFixed(0)}%</div>
            <div className="flex items-center gap-2"><MapPin size={16} className="text-cyan-400" /> GPS_STABLE</div>
            <div className="flex items-center gap-2"><Radio size={16} className="text-cyan-400" /> LINK: 98%</div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className={`px-4 py-1 border rounded text-[10px] font-black tracking-widest ${currentMode === FlightMode.AUTO_FOLLOW || currentMode === FlightMode.AUTONOMOUS ? 'bg-green-900/40 border-green-500 text-green-400 animate-pulse' : 'bg-cyan-900/20 border-cyan-500 text-cyan-400'}`}>
            FLIGHT_MODE: {currentMode}
          </div>
          <button onClick={() => { setLockedTargetId(null); setCurrentMode(FlightMode.ASSISTED); setIsEmergency(false); }} className="p-2 hover:bg-zinc-800 rounded text-zinc-400"><RefreshCw size={18} /></button>
        </div>
      </div>

      {/* Suggestion Bar */}
      <div className={`mb-4 hud-border p-2 rounded flex items-center gap-3 backdrop-blur-md transition-all z-50 ${isExecutingSuggestion ? 'bg-green-600/30 border-green-400' : 'bg-zinc-900/40 border-zinc-700/50'}`}>
        <div className={`p-1.5 rounded-full ${isExecutingSuggestion ? 'bg-white text-green-600 animate-spin' : 'bg-cyan-500 text-black'}`}>
          {isExecutingSuggestion ? <RefreshCw size={14} /> : (lockedTargetId ? <Lock size={14} /> : <Search size={14} />)}
        </div>
        <div className="flex-1">
          <div className="text-[9px] font-black uppercase tracking-widest flex gap-2">
            <span className="text-zinc-500">Lock Target:</span>
            <span className="text-white">{lockedTargetId || 'IDLE'}</span>
            {trackingDecision && (
              <>
                <span className="text-zinc-500 ml-2">Conf:</span>
                <span className="text-cyan-400">{(trackingDecision.lock_confidence * 100).toFixed(0)}%</span>
              </>
            )}
          </div>
          <div className="text-xs font-bold text-zinc-200 truncate">
            {isExecutingSuggestion ? 'AUTONOMOUS VECTORING ACTIVE...' : trackingDecision?.suggested_action || 'Scanning tactical environment...'}
          </div>
        </div>
        <button
          onClick={handleFollowSuggestion}
          disabled={!trackingDecision || trackingDecision.lock_confidence < 0.4 || isExecutingSuggestion}
          className={`px-6 py-2 rounded flex items-center gap-2 font-black text-[10px] uppercase border-b-4 transition-all ${
            trackingDecision && trackingDecision.lock_confidence >= 0.7 
              ? 'bg-green-600 border-green-800 text-white' 
              : trackingDecision && trackingDecision.lock_confidence >= 0.4
                ? 'bg-yellow-600 border-yellow-800 text-white'
                : 'bg-zinc-800 border-zinc-950 text-zinc-600 cursor-not-allowed opacity-50'
          }`}
        >
          {isExecutingSuggestion ? <Activity size={12} className="animate-bounce" /> : <PlayCircle size={12} />}
          Follow Suggestion
        </button>
      </div>

      <div className="flex flex-1 gap-4 overflow-hidden">
        {/* Left Stats */}
        <div className="w-1/5 flex flex-col gap-4">
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase font-black block mb-1">ALT (m)</span>
            <div className="text-3xl font-black">{telemetry.altitude.toFixed(1)}</div>
          </div>
          <div className="hud-border bg-zinc-900/40 p-4 rounded-lg border-l-4 border-l-cyan-500">
            <span className="text-[10px] text-zinc-500 uppercase font-black block mb-1">SPD (km/h)</span>
            <div className="text-3xl font-black">{telemetry.speed.toFixed(1)}</div>
          </div>
          <div className="flex-1 hud-border bg-zinc-900/40 rounded-lg p-3 flex flex-col gap-2">
            <span className="text-[9px] text-zinc-500 font-black uppercase">Tactical Feed Trend</span>
            <div className="flex-1 overflow-hidden opacity-30">
               <ResponsiveContainer width="100%" height="100%">
                 <AreaChart data={telemetryHistory}><Area type="monotone" dataKey="alt" stroke="#00ffcc" fill="#00ffcc" /></AreaChart>
               </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Video Feed & Control Panel */}
        <div className="flex-1 flex flex-col gap-4">
          <div className="flex-1 relative bg-black rounded-lg border border-zinc-800 overflow-hidden shadow-2xl">
            {cameraActive ? (
              <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity ${isEmergency ? 'opacity-30' : 'opacity-60'}`} />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-zinc-800 text-[10px] font-black uppercase"><VideoOff size={48} className="mb-2" /> Feed Offline</div>
            )}

            {/* In-HUD Target Controls */}
            {potentialTargets.map(t => (
              <div 
                key={t.id} 
                className="absolute transition-all duration-300 pointer-events-none"
                style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.width}%`, height: `${t.height}%` }}
              >
                <div className={`absolute inset-0 border-2 ${lockedTargetId === t.id ? 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'border-cyan-500/40'}`}>
                   <button 
                     onClick={(e) => { e.stopPropagation(); handleTargetToggle(t.id); }}
                     className={`absolute -top-12 left-1/2 -translate-x-1/2 pointer-events-auto px-4 py-1.5 rounded-full border text-[9px] font-black uppercase transition-all flex items-center gap-1.5 ${
                        lockedTargetId === t.id 
                        ? 'bg-red-600 border-red-400 text-white hover:bg-red-500' 
                        : 'bg-black/80 border-cyan-500/50 text-cyan-400 hover:bg-cyan-500 hover:text-black'
                     }`}
                   >
                     {lockedTargetId === t.id ? <Unlock size={10} /> : <Crosshair size={10} />}
                     {lockedTargetId === t.id ? 'DISENGAGE' : 'LOCK TRACK'}
                   </button>
                </div>
                <div className={`absolute -bottom-6 left-0 text-[8px] font-black uppercase ${lockedTargetId === t.id ? 'text-red-500' : 'text-cyan-500 opacity-60'}`}>
                  {t.label} {lockedTargetId === t.id && '(LOCKED)'}
                </div>
              </div>
            ))}
          </div>

          {/* Restored Main Control Panel */}
          <div className="hud-border bg-zinc-900/60 p-3 rounded-lg flex gap-3 shadow-xl">
             <button 
                onClick={() => setCurrentMode(FlightMode.AUTONOMOUS)}
                className={`flex-1 py-3 rounded-lg border flex flex-col items-center justify-center transition-all ${currentMode === FlightMode.AUTONOMOUS ? 'bg-cyan-600 border-cyan-400 text-white' : 'bg-zinc-800/40 border-zinc-700 text-zinc-500'} hover:border-cyan-500`}
             >
                <Navigation size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Autonomous Flight</span>
             </button>
             <button onClick={() => updateTrackingDecision("Manual scan sweep triggered.")} className="flex-1 py-3 rounded-lg bg-zinc-800/40 border border-zinc-700 text-cyan-400 hover:border-cyan-500 flex flex-col items-center justify-center">
                <Search size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Tactical Scan</span>
             </button>
             <button onClick={() => setCurrentMode(FlightMode.RETURN_TO_HOME)} className="flex-1 py-3 rounded-lg bg-zinc-800/40 border border-zinc-700 text-yellow-500 hover:border-yellow-500 flex flex-col items-center justify-center">
                <ArrowUp size={20} className="rotate-180" />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">RTH Mode</span>
             </button>
             <button onClick={() => setCurrentMode(FlightMode.EMERGENCY_LANDING)} className="flex-1 py-3 rounded-lg bg-red-900/20 border border-red-500/40 text-red-500 hover:bg-red-900/40 flex flex-col items-center justify-center">
                <ShieldAlert size={20} />
                <span className="text-[9px] font-black mt-1 uppercase tracking-widest">Force Land</span>
             </button>
          </div>
        </div>

        {/* Command Center (Chat Panel) */}
        <div className="w-1/3 flex flex-col gap-4">
          <div className="flex-1 hud-border bg-black/80 rounded-lg flex flex-col overflow-hidden backdrop-blur-md border-r-4 border-r-cyan-500/50 shadow-2xl">
            <div className="p-3 border-b border-zinc-800 bg-zinc-900/60 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Terminal size={16} className="text-cyan-400" />
                <span className="font-black text-[10px] tracking-widest uppercase">Tactical Terminal</span>
              </div>
              <div className="flex items-center gap-3">
                <div className="text-[8px] font-black text-zinc-600 uppercase tracking-tighter">Secure Link</div>
                <div className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-yellow-500 animate-ping' : 'bg-cyan-500 animate-pulse'}`} />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-4 font-mono text-[10px] scroll-smooth">
              {messages.map((m) => (
                <div key={m.id} className={`flex flex-col gap-1 ${m.type === 'OPERATOR' ? 'items-end' : 'items-start'}`}>
                  <div className="flex items-center gap-2 text-[8px] font-black uppercase tracking-tighter opacity-40">
                    <span>{m.type === 'AI' ? 'Aegis_Core' : m.type}</span>
                    <span>•</span>
                    <span>{m.timestamp}</span>
                  </div>
                  <div className={`max-w-[85%] p-3 rounded-xl border leading-relaxed ${
                    m.type === 'AI' 
                      ? 'bg-cyan-950/20 border-cyan-500/30 text-cyan-50 shadow-[0_0_15px_rgba(0,255,204,0.05)]' 
                      : m.type === 'SYSTEM' ? 'bg-zinc-900/60 border-yellow-500/20 text-yellow-500 italic' 
                      : 'bg-zinc-900/80 border-zinc-700 text-zinc-400'
                  }`}>
                    {m.content}

                    {/* Inline Command Button */}
                    {m.type === 'AI' && m.trackingData && m.trackingData.lock_confidence > 0.4 && (
                      <div className="mt-3 pt-3 border-t border-cyan-500/20">
                        <button 
                          onClick={handleFollowSuggestion}
                          className="w-full bg-cyan-600/20 border border-cyan-500/50 hover:bg-cyan-600/40 text-cyan-400 py-1.5 rounded-lg flex items-center justify-center gap-2 text-[9px] font-black uppercase transition-all"
                        >
                          <PlayCircle size={10} />
                          Execute: {m.trackingData.suggested_action.split(' ').slice(0, 3).join(' ')}...
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-2 text-cyan-400 bg-cyan-900/10 p-2 rounded border border-cyan-900 animate-pulse">
                  <Activity size={12} className="animate-spin" />
                  <span className="text-[9px] font-black uppercase">Analyzing tactical intent...</span>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            <div className="p-3 border-t border-zinc-800 bg-zinc-900/40">
              <div className="relative">
                <input 
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAIRequest()}
                  placeholder="Query system or issue command..."
                  className="w-full bg-black border border-zinc-700 text-cyan-400 pl-4 pr-12 py-3 rounded-xl text-[10px] focus:outline-none focus:border-cyan-500/50 placeholder:text-zinc-700 font-mono"
                />
                <button 
                  onClick={() => handleAIRequest()}
                  disabled={!userInput || isProcessing}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg text-cyan-500 hover:text-cyan-300 disabled:opacity-20 transition-all"
                >
                  <Send size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Status */}
      <div className="mt-4 flex justify-between text-[8px] text-zinc-600 font-mono tracking-widest uppercase">
        <div className="flex gap-4">
          <span>UAV_ALPHA_SEVEN</span>
          <span>UPTIME: {Math.floor(performance.now() / 1000)}S</span>
          <span>SEC: 256_BIT_AES</span>
        </div>
        <div className="flex gap-4">
          <span className="text-cyan-500">AUTONOMOUS_FOLLOW: {currentMode === FlightMode.AUTO_FOLLOW ? 'ACTIVE' : 'READY'}</span>
          <span>SIGNAL_DBM: -42</span>
        </div>
      </div>
    </div>
  );
};

export default App;
